code:
protected void doCrawl(final String sessionId, final List<WebConfig> webConfigList, final List<FileConfig> fileConfigList) {
        final int multiprocessCrawlingCount = ComponentUtil.getFessConfig().getCrawlingThreadCount();

        final SystemHelper systemHelper = ComponentUtil.getSystemHelper();
        ComponentUtil.getFessConfig();
        final ProtocolHelper protocolHelper = ComponentUtil.getProtocolHelper();

        final long startTime = systemHelper.getCurrentTimeAsLong();

        final List<String> sessionIdList = new ArrayList<>();
        crawlerList.clear();
        final List<String> crawlerStatusList = new ArrayList<>();
        // Web
        for (final WebConfig webConfig : webConfigList) {
            final String sid = ComponentUtil.getCrawlingConfigHelper().store(sessionId, webConfig);

            // create crawler
            final Crawler crawler = ComponentUtil.getComponent(Crawler.class);
            crawler.setSessionId(sid);
            sessionIdList.add(sid);

            final String urlsStr = webConfig.getUrls();
            if (StringUtil.isBlank(urlsStr)) {
                logger.warn("[{}] No target urls. Skipped.", webConfig.getName());
                break;
            }

            // interval time
            final int intervalTime =
                    webConfig.getIntervalTime() != null ? webConfig.getIntervalTime() : Constants.DEFAULT_INTERVAL_TIME_FOR_WEB;
            ((FessIntervalController) crawler.getIntervalController()).setDelayMillisForWaitingNewUrl(intervalTime);

            final String includedUrlsStr = webConfig.getIncludedUrls() != null ? webConfig.getIncludedUrls() : StringUtil.EMPTY;
            final String excludedUrlsStr = webConfig.getExcludedUrls() != null ? webConfig.getExcludedUrls() : StringUtil.EMPTY;

            // num of threads
            final CrawlerContext crawlerContext = crawler.getCrawlerContext();
            final int numOfThread =
                    webConfig.getNumOfThread() != null ? webConfig.getNumOfThread() : Constants.DEFAULT_NUM_OF_THREAD_FOR_WEB;
            crawlerContext.setNumOfThread(numOfThread);

            // depth
            final int depth = webConfig.getDepth() != null ? webConfig.getDepth() : -1;
            crawlerContext.setMaxDepth(depth);

            // max count
            final long maxCount = webConfig.getMaxAccessCount() != null ? webConfig.getMaxAccessCount() : maxAccessCount;
            crawlerContext.setMaxAccessCount(maxCount);

            webConfig.initializeClientFactory(() -> crawler.getClientFactory());
            final Map<String, String> configParamMap = webConfig.getConfigParameterMap(ConfigName.CONFIG);

            if (Constants.TRUE.equalsIgnoreCase(configParamMap.get(Config.CLEANUP_ALL))) {
                deleteCrawlData(sid);
            } else if (Constants.TRUE.equalsIgnoreCase(configParamMap.get(Config.CLEANUP_URL_FILTERS))) {
                final OpenSearchUrlFilterService urlFilterService = ComponentUtil.getComponent(OpenSearchUrlFilterService.class);
                try {
                    urlFilterService.delete(sid);
                } catch (final Exception e) {
                    logger.warn("Failed to delete UrlFilter: sessionId={}", sid);
                }
            }

            final DuplicateHostHelper duplicateHostHelper = ComponentUtil.getDuplicateHostHelper();

            // set urls
            split(urlsStr, "[\r\n]").of(stream -> stream.filter(StringUtil::isNotBlank).map(String::trim).distinct().forEach(urlValue -> {
                if (!urlValue.startsWith("#")) {
                    if (protocolHelper.isValidWebProtocol(urlValue)) {
                        final String u = duplicateHostHelper.convert(urlValue);
                        crawler.addUrl(u);
                        if (logger.isInfoEnabled()) {
                            logger.info("Target URL: {}", u);
                        }
                    } else {
                        // Unlike a file crawling path, which falls back to file:, a web URL with an
                        // unusable protocol is dropped, and used to be dropped without a trace: the
                        // job then succeeded having crawled nothing.
                        logger.warn("Unsupported protocol in a crawling URL: {}. It is skipped. Available web protocols are {} ({}).",
                                urlValue, ComponentUtil.getFessConfig().getCrawlerWebProtocols(), FessConfig.CRAWLER_WEB_PROTOCOLS);
                    }
                }
            }));

            // set included urls
            final AtomicBoolean urlEncodeDisabled = new AtomicBoolean(false);
            split(includedUrlsStr, "[\r\n]").of(stream -> stream.filter(StringUtil::isNotBlank).map(String::trim).forEach(line -> {
                if (!line.startsWith("#")) {
                    final String urlValue;
                    if (urlEncodeDisabled.get()) {
                        urlValue = line;
                        urlEncodeDisabled.set(false);
                    } else {
                        urlValue = systemHelper.encodeUrlFilter(line);
                    }
                    crawler.addIncludeFilter(urlValue);
                    if (logger.isInfoEnabled()) {
                        logger.info("Included URL: {}", urlValue);
                    }
                } else if (line.startsWith(DISABLE_URL_ENCODE)) {
                    urlEncodeDisabled.set(true);
                }
            }));

            // set excluded urls
            urlEncodeDisabled.set(false);
            split(excludedUrlsStr, "[\r\n]").of(stream -> stream.filter(StringUtil::isNotBlank).map(String::trim).forEach(line -> {
                if (!line.startsWith("#")) {
                    final String urlValue;
                    if (urlEncodeDisabled.get()) {
                        urlValue = line;
                        urlEncodeDisabled.set(false);
                    } else {
                        urlValue = systemHelper.encodeUrlFilter(line);
                    }
                    crawler.addExcludeFilter(urlValue);
                    if (logger.isInfoEnabled()) {
                        logger.info("Excluded URL: {}", urlValue);
                    }
                } else if (line.startsWith(DISABLE_URL_ENCODE)) {
                    urlEncodeDisabled.set(true);
                }
            }));

            // failure url
            final List<String> excludedUrlList = ComponentUtil.getCrawlingConfigHelper().getExcludedUrlList(webConfig.getConfigId());
            if (excludedUrlList != null) {
                excludedUrlList.stream().filter(StringUtil::isNotBlank).map(String::trim).distinct().forEach(u -> {
                    final String urlValue = Pattern.quote(u);
                    crawler.addExcludeFilter(urlValue);
                    if (logger.isInfoEnabled()) {
                        logger.info("Excluded URL from failures: {}", urlValue);
                    }
                });
            }

            if (logger.isDebugEnabled()) {
                logger.debug("Crawling {}", urlsStr);
            }

            crawler.setBackground(true);
            crawler.setThreadPriority(crawlerPriority);

            crawlerList.add(crawler);
            crawlerStatusList.add(Constants.READY);
        }

        // File
        for (final FileConfig fileConfig : fileConfigList) {
            final String sid = ComponentUtil.getCrawlingConfigHelper().store(sessionId, fileConfig);

            // create crawler
            final Crawler crawler = ComponentUtil.getComponent(Crawler.class);
            crawler.setSessionId(sid);
            sessionIdList.add(sid);

            final String pathsStr = fileConfig.getPaths();
            if (StringUtil.isBlank(pathsStr)) {
                logger.warn("[{}] No target uris. Skipped.", fileConfig.getName());
                break;
            }

            final int intervalTime =
                    fileConfig.getIntervalTime() != null ? fileConfig.getIntervalTime() : Constants.DEFAULT_INTERVAL_TIME_FOR_FS;
            ((FessIntervalController) crawler.getIntervalController()).setDelayMillisForWaitingNewUrl(intervalTime);

            final String includedPathsStr = fileConfig.getIncludedPaths() != null ? fileConfig.getIncludedPaths() : StringUtil.EMPTY;
            final String excludedPathsStr = fileConfig.getExcludedPaths() != null ? fileConfig.getExcludedPaths() : StringUtil.EMPTY;

            // num of threads
            final CrawlerContext crawlerContext = crawler.getCrawlerContext();
            final int numOfThread =
                    fileConfig.getNumOfThread() != null ? fileConfig.getNumOfThread() : Constants.DEFAULT_NUM_OF_THREAD_FOR_FS;
            crawlerContext.setNumOfThread(numOfThread);

            // depth
            final int depth = fileConfig.getDepth() != null ? fileConfig.getDepth() : -1;
            crawlerContext.setMaxDepth(depth);

            // max count
            final long maxCount = fileConfig.getMaxAccessCount() != null ? fileConfig.getMaxAccessCount() : maxAccessCount;
            crawlerContext.setMaxAccessCount(maxCount);

            fileConfig.initializeClientFactory(() -> crawler.getClientFactory());
            final Map<String, String> configParamMap = fileConfig.getConfigParameterMap(ConfigName.CONFIG);

            if (Constants.TRUE.equalsIgnoreCase(configParamMap.get(Config.CLEANUP_ALL))) {
                deleteCrawlData(sid);
            } else if (Constants.TRUE.equalsIgnoreCase(configParamMap.get(Config.CLEANUP_URL_FILTERS))) {
                final OpenSearchUrlFilterService urlFilterService = ComponentUtil.getComponent(OpenSearchUrlFilterService.class);
                try {
                    urlFilterService.delete(sid);
                } catch (final Exception e) {
                    logger.warn("Failed to delete UrlFilter: sessionId={}", sid);
                }
            }

            // set paths
            split(pathsStr, "[\r\n]").of(stream -> stream.filter(StringUtil::isNotBlank).map(String::trim).distinct().forEach(urlValue -> {
                if (!urlValue.startsWith("#")) {
                    final String u;
                    if (!protocolHelper.isValidFileProtocol(urlValue)) {
                        if (isUnsupportedProtocol(urlValue, protocolHelper.getFileProtocols())) {
                            logger.warn(
                                    "Unsupported protocol in a crawling path: {}. It is crawled as a local file path. Available file protocols are {} ({}). The plugin that provides this protocol may not be installed.",
                                    urlValue, ComponentUtil.getFessConfig().getCrawlerFileProtocols(), FessConfig.CRAWLER_FILE_PROTOCOLS);
                        }
                        if (urlValue.startsWith("/")) {
                            u = "file:" + urlValue;
                        } else {
                            u = "file:/" + urlValue;
                        }
                    } else {
                        u = urlValue;
                    }
                    if (crawler.getClientFactory().getClient(u) == null) {
                        // The other half of the report above: there, the protocol is not configured
                        // at all; here it is, but nothing is registered to fetch it. An installation
                        // that upgrades keeps its own crawler.file.protocols, so this is the shape a
                        // missing protocol plugin takes for it. fess-crawler only logs the skip at
                        // info level, per URL, once the crawl is under way.
                        logger.warn(
                                "No crawler client is registered for a crawling path: {}. It is not crawled. The plugin that provides this protocol may not be installed.",
                                u);
                    }
                    crawler.addUrl(u);
                    if (logger.isInfoEnabled()) {
                        logger.info("Target Path: {}", u);
                    }
                }
            }));

            // set included paths
            final AtomicBoolean urlEncodeDisabled = new AtomicBoolean(false);
            split(includedPathsStr, "[\r\n]").of(stream -> stream.filter(StringUtil::isNotBlank).map(String::trim).forEach(line -> {
                if (!line.startsWith("#")) {
                    final String urlValue;
                    if (urlEncodeDisabled.get()) {
                        urlValue = line;
                        urlEncodeDisabled.set(false);
                    } else {
                        urlValue = systemHelper.encodeUrlFilter(line);
                    }
                    crawler.addIncludeFilter(urlValue);
                    if (logger.isInfoEnabled()) {
                        logger.info("Included Path: {}", urlValue);
                    }
                } else if (line.startsWith(DISABLE_URL_ENCODE)) {
                    urlEncodeDisabled.set(true);
                }
            }));

            // set excluded paths
            urlEncodeDisabled.set(false);
            split(excludedPathsStr, "[\r\n]").of(stream -> stream.filter(StringUtil::isNotBlank).map(String::trim).forEach(line -> {
                if (!line.startsWith("#")) {
                    final String urlValue;
                    if (urlEncodeDisabled.get()) {
                        urlValue = line;
                        urlEncodeDisabled.set(false);
                    } else {
                        urlValue = systemHelper.encodeUrlFilter(line);
                    }
                    crawler.addExcludeFilter(urlValue);
                    if (logger.isInfoEnabled()) {
                        logger.info("Excluded Path: {}", urlValue);
                    }
                } else if (line.startsWith(DISABLE_URL_ENCODE)) {
                    urlEncodeDisabled.set(true);
                }
            }));

            // failure url
            final List<String> excludedUrlList = ComponentUtil.getCrawlingConfigHelper().getExcludedUrlList(fileConfig.getConfigId());
            if (excludedUrlList != null) {
                excludedUrlList.stream().filter(StringUtil::isNotBlank).map(String::trim).distinct().forEach(u -> {
                    final String urlValue = Pattern.quote(u);
                    crawler.addExcludeFilter(urlValue);
                    if (logger.isInfoEnabled()) {
                        logger.info("Excluded Path from failures: {}", urlValue);
                    }
                });
            }

            if (logger.isDebugEnabled()) {
                logger.debug("Crawling {}", pathsStr);
            }

            crawler.setBackground(true);
            crawler.setThreadPriority(crawlerPriority);

            crawlerList.add(crawler);
            crawlerStatusList.add(Constants.READY);
        }

        // run index update
        final IndexUpdater indexUpdater = ComponentUtil.getIndexUpdater();
        indexUpdater.setName("IndexUpdater");
        indexUpdater.setPriority(indexUpdaterPriority);
        indexUpdater.setSessionIdList(sessionIdList);
        indexUpdater.setDaemon(true);
        indexUpdater.setCrawlerList(crawlerList);
        getAvailableBoostDocumentRuleList().forEach(rule -> {
            indexUpdater.addDocBoostMatcher(new org.codelibs.fess.indexer.DocBoostMatcher(rule));
        });
        indexUpdater.start();

        int startedCrawlerNum = 0;
        int activeCrawlerNum = 0;
        try {
            while (startedCrawlerNum < crawlerList.size()) {
                // Force to stop crawl
                if (systemHelper.isForceStop()) {
                    for (final Crawler crawler : crawlerList) {
                        crawler.stop();
                    }
                    break;
                }

                if (activeCrawlerNum < multiprocessCrawlingCount) {
                    // start crawling
                    crawlerList.get(startedCrawlerNum).execute();
                    crawlerStatusList.set(startedCrawlerNum, Constants.RUNNING);
                    startedCrawlerNum++;
                    activeCrawlerNum++;
                    ThreadUtil.sleep(crawlingExecutionInterval);
                    continue;
                }

                // check status
                for (int i = 0; i < startedCrawlerNum; i++) {
                    if (crawlerList.get(i).getCrawlerContext().getStatus() == CrawlerStatus.DONE
                            && Constants.RUNNING.equals(crawlerStatusList.get(i))) {
                        crawlerList.get(i).awaitTermination();
                        crawlerStatusList.set(i, Constants.DONE);
                        final String sid = crawlerList.get(i).getCrawlerContext().getSessionId();
                        indexUpdater.addFinishedSessionId(sid);
                        activeCrawlerNum--;
                    }
                }
                ThreadUtil.sleep(crawlingExecutionInterval);
            }

            boolean finishedAll = false;
            while (!finishedAll) {
                finishedAll = true;
                for (int i = 0; i < crawlerList.size(); i++) {
                    final Crawler crawler = crawlerList.get(i);
                    crawler.awaitTermination(crawlingExecutionInterval);
                    if (crawler.getCrawlerContext().getStatus() == CrawlerStatus.DONE && !Constants.DONE.equals(crawlerStatusList.get(i))) {
                        crawlerStatusList.set(i, Constants.DONE);
                        final String sid = crawler.getCrawlerContext().getSessionId();
                        indexUpdater.addFinishedSessionId(sid);
                        try {
                            crawler.close();
                        } catch (final Exception e) {
                            logger.warn("Failed to close the crawler.", e);
                        }
                    }
                    if (!Constants.DONE.equals(crawlerStatusList.get(i))) {
                        finishedAll = false;
                    }
                }
            }
        } finally {
            crawlerList.forEach(crawler -> {
                try {
                    crawler.close();
                } catch (final Exception e) {
                    logger.warn("Failed to close the crawler.", e);
                }
            });
        }
        crawlerList.clear();
        crawlerStatusList.clear();

        // put cralwing info
        final CrawlingInfoHelper crawlingInfoHelper = ComponentUtil.getCrawlingInfoHelper();

        final long execTime = systemHelper.getCurrentTimeAsLong() - startTime;
        crawlingInfoHelper.putToInfoMap(Constants.WEB_FS_CRAWLING_EXEC_TIME, Long.toString(execTime));
        if (logger.isInfoEnabled()) {
            logger.info("[EXEC TIME] crawling time: {}ms", execTime);
        }

        indexUpdater.setFinishCrawling(true);
        try {
            indexUpdater.join();
        } catch (final InterruptedException e) {
            logger.warn("Interrupted index update.", e);
        }

        crawlingInfoHelper.putToInfoMap(Constants.WEB_FS_INDEX_EXEC_TIME, Long.toString(indexUpdater.getExecuteTime()));
        crawlingInfoHelper.putToInfoMap(Constants.WEB_FS_INDEX_SIZE, Long.toString(indexUpdater.getDocumentSize()));

        if (systemHelper.isForceStop()) {
            return;
        }

        for (final String sid : sessionIdList) {
            // remove config
            ComponentUtil.getCrawlingConfigHelper().remove(sid);
            deleteCrawlData(sid);
        }
    }

public void handle(final HttpServletRequest req, final HttpServletResponse res) throws IOException {
        if (!"POST".equalsIgnoreCase(req.getMethod())) {
            res.setHeader("Allow", "POST");
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.METHOD_NOT_ALLOWED, "method not allowed");
            return;
        }
        // M-17: split DI-binding/lookup failure from "no user bean present". A genuine
        // anonymous caller still produces AUTH_REQUIRED (401); a system-level lookup
        // failure produces INTERNAL_ERROR (500) so the user does not see a misleading
        // "please log in again" when the real issue is server-side.
        final FessLoginAssist assist;
        try {
            assist = ComponentUtil.getFessLoginAssist();
        } catch (final RuntimeException e) {
            logger.warn("/api/v2/auth/password: could not acquire FessLoginAssist", e);
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INTERNAL_ERROR, "internal error");
            return;
        }
        final OptionalThing<FessUserBean> userBean;
        try {
            userBean = assist.getSavedUserBean();
        } catch (final RuntimeException e) {
            logger.warn("/api/v2/auth/password: getSavedUserBean failed", e);
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INTERNAL_ERROR, "internal error");
            return;
        }
        if (!userBean.isPresent()) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.AUTH_REQUIRED, "login required");
            return;
        }
        final Map<String, Object> body;
        try {
            body = ComponentUtil.getV2JsonBody().read(req, MAX_BODY_BYTES);
        } catch (final V2JsonBody.PayloadTooLargeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.PAYLOAD_TOO_LARGE, e.getMessage());
            return;
        } catch (final V2JsonBody.UnsupportedMediaTypeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.UNSUPPORTED_MEDIA_TYPE, e.getMessage());
            return;
        } catch (final V2JsonBody.MalformedJsonException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, e.getMessage());
            return;
        }
        final String currentPw = stringOrNull(body.get("current_password"));
        final String newPw = stringOrNull(body.get("new_password"));
        final String confirm = stringOrNull(body.get("confirm_password"));
        if (StringUtil.isBlank(currentPw)) {
            ComponentUtil.getV2EnvelopeWriter()
                    .writeErrorWithDetails(res, V2ErrorCode.INVALID_REQUEST, "current_password is required",
                            Map.of("reason", "current_password_required"));
            return;
        }
        try {
            final int maxPwLen = ComponentUtil.getFessConfig().getPasswordMaxLengthOrDefault();
            if (currentPw.length() > maxPwLen) {
                throw new InvalidRequestParameterException("current_password exceeds the maximum length of " + maxPwLen);
            }
            if (confirm != null && confirm.length() > maxPwLen) {
                throw new InvalidRequestParameterException("confirm_password exceeds the maximum length of " + maxPwLen);
            }
        } catch (final InvalidRequestParameterException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, e.getMessage());
            return;
        }
        if (newPw == null || newPw.isBlank()) {
            ComponentUtil.getV2EnvelopeWriter()
                    .writeErrorWithDetails(res, V2ErrorCode.INVALID_REQUEST, "new_password is required",
                            Map.of("reason", "new_password_required"));
            return;
        }
        if (!newPw.equals(confirm)) {
            ComponentUtil.getV2EnvelopeWriter()
                    .writeErrorWithDetails(res, V2ErrorCode.INVALID_REQUEST, "passwords do not match",
                            Map.of("reason", "password_mismatch"));
            return;
        }
        final String userId = userBean.get().getUserId();

        // C-3: rate-limit the current_password verification on a per-user bucket. We use the
        // same FessConfig thresholds as /api/v2/auth/login so an operator can tune one set
        // of knobs. peek() short-circuits when the bucket is already exhausted; allow() is
        // called only on the failure path so a system error does not count against the
        // legitimate user's quota.
        final LoginRateLimiter rate = limiter();
        int userLimit = 0;
        int lockoutSec = 0;
        if (rate != null) {
            try {
                final FessConfig fessConfig = ComponentUtil.getFessConfig();
                userLimit = fessConfig.getThemeApiLoginRateLimitPerUserPerMinuteAsInteger();
                lockoutSec = fessConfig.getThemeApiLoginLockoutSecondsAsInteger();
            } catch (final RuntimeException e) {
                // FessConfig unavailable in a slim test harness: keep sentinels (0,0) which
                // makes the limiter calls below into no-ops rather than blocking the flow.
                logger.warn("/api/v2/auth/password: could not read rate-limit config; gate disabled", e);
            }
        }
        if (rate != null && userLimit > 0 && !rate.peek(LoginRateLimiter.Scope.USER, userId, userLimit, 60)) {
            // Only the request that arms the lockout is a new security event; every later
            // request during the same lockout reaches this branch too, so logging them all at
            // WARN would let a stolen-session attacker pump the log without bound.
            if (rate.lockOut(LoginRateLimiter.Scope.USER, userId, lockoutSec)) {
                logger.warn("/api/v2/auth/password: rate limit exceeded; locking out for {}s: userId={}, limit={}/min", lockoutSec, userId,
                        userLimit);
            } else if (logger.isDebugEnabled()) {
                logger.debug("/api/v2/auth/password: refused a retry during the active lockout: userId={}", userId);
            }
            res.setHeader("Retry-After", Integer.toString(Math.max(lockoutSec, 1)));
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.RATE_LIMITED, "too many password-change attempts");
            return;
        }

        // Re-authenticate the current user with the supplied current_password. We mirror
        // ProfileAction.validatePasswordForm — findLoginUser performs the same hash compare
        // that the login flow uses, so we get an early reject for wrong-password without
        // leaking timing differences vs. a hand-rolled compare.
        final OptionalEntity<? extends FessUser> verified;
        try {
            verified = assist.findLoginUser(new LocalUserCredential(userId, currentPw));
        } catch (final RuntimeException e) {
            logger.warn("/api/v2/auth/password: findLoginUser failed", e);
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INTERNAL_ERROR, "failed to change password");
            return;
        }
        if (verified == null || !verified.isPresent()) {
            // Wrong current_password: consume one user-bucket slot. If the bucket has just
            // been exhausted, escalate to 429 with Retry-After (same pattern as LoginHandler).
            if (rate != null && userLimit > 0 && !rate.allow(LoginRateLimiter.Scope.USER, userId, userLimit, 60)) {
                if (rate.lockOut(LoginRateLimiter.Scope.USER, userId, lockoutSec)) {
                    logger.warn("/api/v2/auth/password: rate limit exhausted; locking out for {}s: userId={}, limit={}/min", lockoutSec,
                            userId, userLimit);
                } else if (logger.isDebugEnabled()) {
                    // The peek() gate above admitted this request, so an active lockout here
                    // means a concurrent request armed it in between — already reported.
                    logger.debug("/api/v2/auth/password: bucket exhausted while a lockout was already active: userId={}", userId);
                }
                res.setHeader("Retry-After", Integer.toString(Math.max(lockoutSec, 1)));
                ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.RATE_LIMITED, "too many password-change attempts");
                return;
            }
            ComponentUtil.getV2EnvelopeWriter()
                    .writeErrorWithDetails(res, V2ErrorCode.AUTH_REQUIRED, "invalid current password",
                            Map.of("reason", "invalid_current_password"));
            return;
        }
        final String validationError = ComponentUtil.getSystemHelper().validatePassword(newPw);
        if (StringUtil.isNotBlank(validationError)) {
            final Map<String, Object> details = new LinkedHashMap<>();
            details.put("reason", validationError);
            if ("errors.password_length".equals(validationError)) {
                final Integer minLength = ComponentUtil.getFessConfig().getPasswordMinLengthAsInteger();
                if (minLength != null) {
                    details.put("min_length", minLength);
                }
            }
            ComponentUtil.getV2EnvelopeWriter()
                    .writeErrorWithDetails(res, V2ErrorCode.INVALID_REQUEST, "weak password: " + validationError, details);
            return;
        }
        try {
            ComponentUtil.getComponent(UserService.class).changePassword(userId, newPw);
        } catch (final Exception e) {
            logger.warn("/api/v2/auth/password: changePassword failed", e);
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INTERNAL_ERROR, "failed to change password");
            return;
        }
        // C-3: successful change resets the per-user bucket so any earlier failed attempts
        // in the same window are forgiven — mirrors LoginHandler's MJ-5 reset.
        if (rate != null) {
            rate.clear(LoginRateLimiter.Scope.USER, userId);
        }
        // M-3: invalidate the current session so any exfiltrated session token is
        // immediately revoked. This must happen BEFORE writing the response because the
        // servlet container may flush cookie-clearing headers together with the response.
        // We do NOT rotate-and-return a CSRF token here: the session is destroyed, so any
        // token would belong to a non-existent session and be useless to the SPA.
        //
        // re_login_required:true signals the SPA that the password has changed and it
        // must redirect to the login page to obtain a fresh session and CSRF token.
        // Other concurrent sessions for the same user are NOT invalidated — this is a
        // known limitation (requires a Fess-wide session registry, follow-up item).
        //
        // MINOR-4: call assist.logout() first so that remember-me cookies are cleared —
        // matching the LogoutHandler pattern. Failures are swallowed so that
        // session.invalidate() still runs regardless. Note that assist.logout() writes no
        // audit record of its own: the LOGOUT activity is emitted by the caller (LogoutAction
        // in the classic flow, LogoutHandler on the v2 path), and a password change is not a
        // logout event, so none is written here.
        try {
            assist.logout();
        } catch (final Exception e) {
            // logout is best-effort: unavailable session manager or already-logged-out state
            // must not prevent the session invalidation that follows.
            logger.debug("/api/v2/auth/password: assist.logout() failed for userId={}; continuing session invalidation", userId);
        }
        boolean sessionInvalidated = false;
        final HttpSession session = req.getSession(false);
        if (session != null) {
            try {
                session.invalidate();
                sessionInvalidated = true;
            } catch (final IllegalStateException e) {
                // Already invalidated by another thread, the container, or assist.logout() — safe to ignore.
                logger.debug("/api/v2/auth/password: session was already invalidated for userId={}", userId);
                sessionInvalidated = true;
            }
        }
        logger.info("/api/v2/auth/password: password changed; userId={}, sessionInvalidated={}", userId, sessionInvalidated);
        final Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("ok", true);
        payload.put("re_login_required", true);
        ComponentUtil.getV2EnvelopeWriter().writeSuccess(res, payload);
    }

public ChatResult streamChatEnhanced(final String sessionId, final String userMessage, final String userId,
            final Map<String, String[]> fields, final String[] extraQueries, final ChatPhaseCallback callback) {
        final Map<String, String[]> safeFields = fields != null ? fields : Collections.emptyMap();
        final String[] safeExtraQueries = extraQueries != null ? extraQueries : new String[0];
        final long startTime = System.currentTimeMillis();
        // Capture context path early before request context may become unavailable during SSE processing
        final String contextPath = resolveContextPath();
        // Note: Locale is resolved via LaRequestUtil in LlmClient. During long SSE processing,
        // the request context may become unavailable, falling back to Locale.getDefault().
        if (logger.isDebugEnabled()) {
            logger.debug("[RAG] Starting enhanced streaming chat request. sessionId={}, userId={}, userMessage={}", sessionId, userId,
                    userMessage);
        }

        final ChatSession session = chatSessionManager.getOrCreateSession(sessionId, userId);
        // Extract phase-specific history snapshots before adding current user message.
        // Intent phase uses minimal context; answer phase pairs user/assistant turns.
        final List<LlmMessage> historyForIntent = extractHistoryForIntent(session);
        final List<LlmMessage> historyForAnswer = extractHistoryForAnswer(session);
        // Add user message immediately for session integrity under concurrent access
        final ChatMessage userChatMessage = ChatMessage.userMessage(userMessage);
        session.addMessage(userChatMessage);
        final StringBuilder fullResponse = new StringBuilder();
        List<Map<String, Object>> sources = new ArrayList<>();
        String searchQueryId = null;
        long searchRequestedTime = 0L;
        String finalSearchQuery = null;

        try {
            // Phase 1: Intent Detection
            long phaseStartTime = System.currentTimeMillis();
            callback.onPhaseStart(ChatPhaseCallback.PHASE_INTENT, "Analyzing your question...");
            final IntentDetectionResult intentResult = llmClientManager.detectIntent(userMessage, historyForIntent);
            if (intentResult.isFallback()) {
                callback.onWarning(ChatPhaseCallback.PHASE_INTENT, "reasoning_token_exhausted", "search");
            }
            callback.onPhaseComplete(ChatPhaseCallback.PHASE_INTENT);

            if (logger.isDebugEnabled()) {
                logger.debug("[RAG] Phase {} completed. intent={}, query={}, reasoning={}, phaseElapsedTime={}ms",
                        ChatPhaseCallback.PHASE_INTENT, intentResult.getIntent(), intentResult.getQuery(), intentResult.getReasoning(),
                        System.currentTimeMillis() - phaseStartTime);
            }

            if (intentResult.getIntent() == ChatIntent.UNCLEAR) {
                // Intent is unclear - ask user for clarification
                phaseStartTime = System.currentTimeMillis();
                callback.onPhaseStart(ChatPhaseCallback.PHASE_ANSWER, "Generating response...");
                final LlmStreamCallback rawUnclearCallback = (chunk, done) -> {
                    fullResponse.append(chunk);
                    callback.onChunk(chunk, done);
                };
                final LlmStreamCallback unclearCallback =
                        new PhaseAwareStreamCallback(ChatPhaseCallback.PHASE_ANSWER, callback, rawUnclearCallback);
                llmClientManager.generateUnclearIntentResponse(userMessage, historyForAnswer, unclearCallback);
                callback.onPhaseComplete(ChatPhaseCallback.PHASE_ANSWER);
                if (logger.isDebugEnabled()) {
                    logger.debug("[RAG] Phase {} completed. responseLength={}, phaseElapsedTime={}ms", ChatPhaseCallback.PHASE_ANSWER,
                            fullResponse.length(), System.currentTimeMillis() - phaseStartTime);
                }
            } else if (intentResult.getIntent() == ChatIntent.SUMMARY) {
                // Summary intent - search by URL and generate summary
                final String documentUrl = intentResult.getDocumentUrl();
                phaseStartTime = System.currentTimeMillis();
                callback.onPhaseStart(ChatPhaseCallback.PHASE_SEARCH, "Searching for document...", documentUrl);
                final ChatSearchResult urlSearchResult = searchByUrl(documentUrl);
                final List<Map<String, Object>> urlResults = urlSearchResult.getDocuments();
                searchQueryId = urlSearchResult.getQueryId();
                searchRequestedTime = urlSearchResult.getRequestedTime();
                callback.onPhaseComplete(ChatPhaseCallback.PHASE_SEARCH, Map.of("hitCount", urlResults.size()));
                if (logger.isDebugEnabled()) {
                    logger.debug("[RAG] Phase {} completed. documentUrl={}, resultCount={}, phaseElapsedTime={}ms",
                            ChatPhaseCallback.PHASE_SEARCH, documentUrl, urlResults.size(), System.currentTimeMillis() - phaseStartTime);
                }

                if (urlResults.isEmpty()) {
                    // URL not found - inform user
                    phaseStartTime = System.currentTimeMillis();
                    callback.onPhaseStart(ChatPhaseCallback.PHASE_ANSWER, "Generating response...");
                    final LlmStreamCallback rawDocNotFoundCallback = (chunk, done) -> {
                        fullResponse.append(chunk);
                        callback.onChunk(chunk, done);
                    };
                    final LlmStreamCallback docNotFoundCallback =
                            new PhaseAwareStreamCallback(ChatPhaseCallback.PHASE_ANSWER, callback, rawDocNotFoundCallback);
                    llmClientManager.generateDocumentNotFoundResponse(userMessage, documentUrl, historyForAnswer, docNotFoundCallback);
                } else {
                    // Fetch full content and generate summary
                    phaseStartTime = System.currentTimeMillis();
                    callback.onPhaseStart(ChatPhaseCallback.PHASE_FETCH, "Retrieving document content...");
                    final List<String> docIds = urlResults.stream()
                            .map(doc -> (String) doc.get("doc_id"))
                            .filter(id -> id != null)
                            .collect(Collectors.toList());
                    final List<Map<String, Object>> fullDocs = fetchFullContent(docIds);
                    callback.onPhaseComplete(ChatPhaseCallback.PHASE_FETCH);
                    // fullDocs stays the LLM context; the sources are resolved back to the
                    // search-phase maps, which alone carry content_description/content_title.
                    sources = resolveSourcesFromSearchResults(fullDocs, urlResults);
                    if (logger.isDebugEnabled()) {
                        logger.debug("[RAG] Phase {} completed. docIds={}, fetchedCount={}, phaseElapsedTime={}ms",
                                ChatPhaseCallback.PHASE_FETCH, docIds, fullDocs.size(), System.currentTimeMillis() - phaseStartTime);
                    }

                    phaseStartTime = System.currentTimeMillis();
                    callback.onPhaseStart(ChatPhaseCallback.PHASE_ANSWER, "Generating summary...");
                    final LlmStreamCallback rawSummaryCallback = (chunk, done) -> {
                        fullResponse.append(chunk);
                        callback.onChunk(chunk, done);
                    };
                    final LlmStreamCallback summaryCallback =
                            new PhaseAwareStreamCallback(ChatPhaseCallback.PHASE_ANSWER, callback, rawSummaryCallback);
                    llmClientManager.generateSummaryResponse(userMessage, fullDocs, historyForAnswer, summaryCallback);
                }
                callback.onPhaseComplete(ChatPhaseCallback.PHASE_ANSWER);
                if (logger.isDebugEnabled()) {
                    logger.debug("[RAG] Phase {} completed. responseLength={}, phaseElapsedTime={}ms", ChatPhaseCallback.PHASE_ANSWER,
                            fullResponse.length(), System.currentTimeMillis() - phaseStartTime);
                }
            } else {
                // Phase 2: Search with query
                final String query = StringUtil.isBlank(intentResult.getQuery()) ? userMessage : intentResult.getQuery();
                finalSearchQuery = query;
                phaseStartTime = System.currentTimeMillis();
                callback.onPhaseStart(ChatPhaseCallback.PHASE_SEARCH, "Searching documents...", query);
                final ChatSearchResult querySearchResult = searchWithQueryAndMetadata(query, safeFields, safeExtraQueries);
                List<Map<String, Object>> searchResults = querySearchResult.getDocuments();
                searchQueryId = querySearchResult.getQueryId();
                searchRequestedTime = querySearchResult.getRequestedTime();
                callback.onPhaseComplete(ChatPhaseCallback.PHASE_SEARCH, Map.of("hitCount", searchResults.size()));

                logger.info("[RAG] Search completed. query={}, resultCount={}, elapsedTime={}ms", query, searchResults.size(),
                        System.currentTimeMillis() - phaseStartTime);
                if (logger.isDebugEnabled()) {
                    logger.debug("[RAG] Phase {} completed. query={}, resultCount={}, phaseElapsedTime={}ms",
                            ChatPhaseCallback.PHASE_SEARCH, query, searchResults.size(), System.currentTimeMillis() - phaseStartTime);
                }

                // Fallback: regenerate query if no results
                if (searchResults.isEmpty()) {
                    logger.info("[RAG] Primary search returned 0 results, regenerating query. originalQuery={}", query);
                    final String newQuery = llmClientManager.regenerateQuery(userMessage, query, "no_results", historyForIntent);
                    if (StringUtil.isNotBlank(newQuery) && !newQuery.equals(query)) {
                        logger.info("[RAG] Regenerated query. newQuery={}", newQuery);
                        callback.onFallback(ChatPhaseCallback.PHASE_SEARCH, "no_results", query, newQuery);
                        callback.onPhaseStart(ChatPhaseCallback.PHASE_SEARCH, "Searching with refined query...", newQuery);
                        final ChatSearchResult fallbackResult = searchWithQueryAndMetadata(newQuery, safeFields, safeExtraQueries);
                        searchResults = fallbackResult.getDocuments();
                        finalSearchQuery = newQuery;
                        searchQueryId = fallbackResult.getQueryId();
                        searchRequestedTime = fallbackResult.getRequestedTime();
                        callback.onPhaseComplete(ChatPhaseCallback.PHASE_SEARCH, Map.of("hitCount", searchResults.size()));
                    }
                }

                if (searchResults.isEmpty()) {
                    // No results even after fallback - generate no-results response
                    phaseStartTime = System.currentTimeMillis();
                    callback.onPhaseStart(ChatPhaseCallback.PHASE_ANSWER, "Generating response...");
                    final LlmStreamCallback rawNoResultsCallback = (chunk, done) -> {
                        fullResponse.append(chunk);
                        callback.onChunk(chunk, done);
                    };
                    final LlmStreamCallback noResultsCallback =
                            new PhaseAwareStreamCallback(ChatPhaseCallback.PHASE_ANSWER, callback, rawNoResultsCallback);
                    llmClientManager.generateNoResultsResponse(userMessage, historyForAnswer, noResultsCallback);
                    callback.onPhaseComplete(ChatPhaseCallback.PHASE_ANSWER);
                    if (logger.isDebugEnabled()) {
                        logger.debug("[RAG] Phase {} completed. responseLength={}, phaseElapsedTime={}ms", ChatPhaseCallback.PHASE_ANSWER,
                                fullResponse.length(), System.currentTimeMillis() - phaseStartTime);
                    }
                } else {
                    // Phase 3: Evaluate results
                    phaseStartTime = System.currentTimeMillis();
                    callback.onPhaseStart(ChatPhaseCallback.PHASE_EVALUATE, "Evaluating relevance...");
                    RelevanceEvaluationResult evalResult = llmClientManager.evaluateResults(userMessage, query, searchResults);
                    callback.onPhaseComplete(ChatPhaseCallback.PHASE_EVALUATE);

                    if (logger.isDebugEnabled()) {
                        logger.debug("[RAG] Phase {} completed. hasRelevant={}, relevantDocIds={}, phaseElapsedTime={}ms",
                                ChatPhaseCallback.PHASE_EVALUATE, evalResult.isHasRelevantResults(), evalResult.getRelevantDocIds(),
                                System.currentTimeMillis() - phaseStartTime);
                    }

                    // Fallback: regenerate query if no relevant results
                    if (!evalResult.isHasRelevantResults()) {
                        logger.info("[RAG] No relevant results in evaluation, regenerating query. originalQuery={}", query);
                        final String newQuery =
                                llmClientManager.regenerateQuery(userMessage, query, "no_relevant_results", historyForIntent);

                        boolean fallbackSucceeded = false;
                        if (StringUtil.isNotBlank(newQuery) && !newQuery.equals(query)) {
                            callback.onFallback(ChatPhaseCallback.PHASE_SEARCH, "no_relevant_results", query, newQuery);
                            callback.onPhaseStart(ChatPhaseCallback.PHASE_SEARCH, "Searching with refined query...", newQuery);
                            final ChatSearchResult fallbackResult = searchWithQueryAndMetadata(newQuery, safeFields, safeExtraQueries);
                            final List<Map<String, Object>> fallbackSearchResults = fallbackResult.getDocuments();
                            callback.onPhaseComplete(ChatPhaseCallback.PHASE_SEARCH, Map.of("hitCount", fallbackSearchResults.size()));

                            if (!fallbackSearchResults.isEmpty()) {
                                // Re-evaluate fallback results
                                callback.onPhaseStart(ChatPhaseCallback.PHASE_EVALUATE, "Evaluating relevance...");
                                final RelevanceEvaluationResult fallbackEvalResult =
                                        llmClientManager.evaluateResults(userMessage, newQuery, fallbackSearchResults);
                                callback.onPhaseComplete(ChatPhaseCallback.PHASE_EVALUATE);

                                if (fallbackEvalResult.isHasRelevantResults()) {
                                    searchResults = fallbackSearchResults;
                                    searchQueryId = fallbackResult.getQueryId();
                                    searchRequestedTime = fallbackResult.getRequestedTime();
                                    evalResult = fallbackEvalResult;
                                    finalSearchQuery = newQuery;
                                    fallbackSucceeded = true;
                                }
                            }
                        }

                        if (!fallbackSucceeded) {
                            // All fallbacks failed - generate no-results response
                            phaseStartTime = System.currentTimeMillis();
                            callback.onPhaseStart(ChatPhaseCallback.PHASE_ANSWER, "Generating response...");
                            final LlmStreamCallback rawFallbackNoResultsCallback = (chunk, done) -> {
                                fullResponse.append(chunk);
                                callback.onChunk(chunk, done);
                            };
                            final LlmStreamCallback fallbackNoResultsCallback =
                                    new PhaseAwareStreamCallback(ChatPhaseCallback.PHASE_ANSWER, callback, rawFallbackNoResultsCallback);
                            llmClientManager.generateNoResultsResponse(userMessage, historyForAnswer, fallbackNoResultsCallback);
                            callback.onPhaseComplete(ChatPhaseCallback.PHASE_ANSWER);
                            if (logger.isDebugEnabled()) {
                                logger.debug("[RAG] Phase {} completed. responseLength={}, phaseElapsedTime={}ms",
                                        ChatPhaseCallback.PHASE_ANSWER, fullResponse.length(), System.currentTimeMillis() - phaseStartTime);
                            }
                        }
                    }

                    if (evalResult.isHasRelevantResults()) {
                        // Phase 4: Fetch full content
                        phaseStartTime = System.currentTimeMillis();
                        callback.onPhaseStart(ChatPhaseCallback.PHASE_FETCH, "Retrieving document content...");
                        final List<Map<String, Object>> fullDocs = ComponentUtil.getChatContentFetcher()
                                .fetchContent(new ChatContentRequest(evalResult.getRelevantDocIds(), searchResults, finalSearchQuery));
                        callback.onPhaseComplete(ChatPhaseCallback.PHASE_FETCH);
                        // fullDocs stays the LLM context; the sources are resolved back to the
                        // search-phase maps, which alone carry content_description/content_title.
                        sources = resolveSourcesFromSearchResults(fullDocs, searchResults);

                        if (logger.isDebugEnabled()) {
                            logger.debug("[RAG] Phase {} completed. docIds={}, fetchedCount={}, phaseElapsedTime={}ms",
                                    ChatPhaseCallback.PHASE_FETCH, evalResult.getRelevantDocIds(), fullDocs.size(),
                                    System.currentTimeMillis() - phaseStartTime);
                        }

                        // Phase 5: Generate answer
                        phaseStartTime = System.currentTimeMillis();
                        callback.onPhaseStart(ChatPhaseCallback.PHASE_ANSWER, "Generating response...");
                        final LlmStreamCallback rawAnswerCallback = (chunk, done) -> {
                            fullResponse.append(chunk);
                            callback.onChunk(chunk, done);
                        };
                        final LlmStreamCallback answerCallback =
                                new PhaseAwareStreamCallback(ChatPhaseCallback.PHASE_ANSWER, callback, rawAnswerCallback);
                        if (intentResult.getIntent() == ChatIntent.FAQ) {
                            llmClientManager.generateFaqAnswerResponse(userMessage, fullDocs, historyForAnswer, answerCallback);
                        } else {
                            llmClientManager.streamGenerateAnswer(userMessage, fullDocs, historyForAnswer, answerCallback);
                        }
                        callback.onPhaseComplete(ChatPhaseCallback.PHASE_ANSWER);
                        if (logger.isDebugEnabled()) {
                            logger.debug("[RAG] Phase {} completed. responseLength={}, sourceCount={}, phaseElapsedTime={}ms",
                                    ChatPhaseCallback.PHASE_ANSWER, fullResponse.length(), fullDocs.size(),
                                    System.currentTimeMillis() - phaseStartTime);
                        }
                    }
                }
            }

            // Phase 6: Render markdown to safe HTML
            final long renderStartTime = System.currentTimeMillis();
            final String htmlContent = renderMarkdownToHtml(fullResponse.toString());
            if (logger.isDebugEnabled()) {
                logger.debug("[RAG] Markdown rendering completed. markdownLength={}, htmlLength={}, renderElapsedTime={}ms",
                        fullResponse.length(), htmlContent.length(), System.currentTimeMillis() - renderStartTime);
            }

            // Create and save assistant message (user message was already added at the start)
            final ChatMessage assistantMessage = ChatMessage.assistantMessage(fullResponse.toString());
            assistantMessage.setHtmlContent(htmlContent);

            for (final Map<String, Object> element : sources) {
                populateUrlLink(element);
            }
            addSourcesToMessage(assistantMessage, sources, contextPath, searchQueryId, searchRequestedTime);

            assistantMessage.setSearchQuery(finalSearchQuery);
            session.addMessage(assistantMessage);

            logger.info(
                    "[RAG] Enhanced chat completed. sessionId={}, userId={}, intent={}, sourcesCount={}, responseLength={}, elapsedTime={}ms",
                    session.getSessionId(), userId, intentResult.getIntent(), sources.size(), fullResponse.length(),
                    System.currentTimeMillis() - startTime);

            return new ChatResult(session.getSessionId(), assistantMessage, sources);

        } catch (final LlmException e) {
            logger.warn("[RAG] LLM error during enhanced chat. sessionId={}, errorCode={}, error={}, elapsedTime={}ms",
                    session.getSessionId(), e.getErrorCode(), e.getMessage(), System.currentTimeMillis() - startTime, e);
            callback.onError("llm", e.getErrorCode());
            throw e;
        } catch (final Exception e) {
            logger.warn("[RAG] Unexpected error during enhanced chat. sessionId={}, error={}, elapsedTime={}ms", session.getSessionId(),
                    e.getMessage(), System.currentTimeMillis() - startTime, e);
            callback.onError("unknown", LlmException.ERROR_UNKNOWN);
            throw e;
        } finally {
            session.trimHistory(getMaxHistoryMessages());
        }
    }

protected List<Map<String, Object>> searchWithMultipleSearchers(final RankFusionSearcher[] searchers, final String query,
            final SearchRequestParams params, final OptionalThing<FessUserBean> userBean) {
        if (logger.isDebugEnabled()) {
            logger.debug("Sending query to searchers: query={}", query);
        }
        final int pageSize = params.getPageSize();
        final int startPosition = params.getStartPosition();
        if (startPosition * 2 >= windowSize) {
            if (logger.isDebugEnabled()) {
                logger.debug("Deep pagination detected: startPosition={}, windowSize={}, falling back to main searcher", startPosition,
                        windowSize);
            }
            int offset = params.getOffset();
            if (offset < 0) {
                offset = 0;
            } else if (offset > windowSize / 2) {
                offset = windowSize / 2;
            }
            int start = startPosition - offset;
            if (start < 0) {
                start = 0;
            }
            if (logger.isDebugEnabled()) {
                logger.debug("Adjusted start position: original={}, adjusted={}, offset={}", startPosition, start, offset);
            }
            final SearchRequestParams reqParams = new SearchRequestParamsWrapper(params, start, pageSize);
            final SearchResult searchResult = searchers[0].search(query, reqParams, userBean);
            long allRecordCount = searchResult.getAllRecordCount();
            if (Relation.EQUAL_TO.toString().equals(searchResult.getAllRecordCountRelation())) {
                allRecordCount += offset;
            }
            return createResponseList(searchResult.getDocumentList(), allRecordCount, searchResult.getAllRecordCountRelation(),
                    searchResult.getQueryTime(), searchResult.isPartialResults(), searchResult.isTimedOut(), searchResult.isShardFailed(),
                    searchResult.getFacetResponse(), params.getStartPosition(), pageSize, offset);
        }

        final ExternalContext externalContext = SingletonLaContainerFactory.getExternalContext();
        final OptionalThing<HttpServletRequest> requestOpt = LaRequestUtil.getOptionalRequest();
        final OptionalThing<HttpServletResponse> responseOpt = LaResponseUtil.getOptionalResponse();
        final FessConfig fessConfig = ComponentUtil.getFessConfig();
        final int rankConstant = fessConfig.getRankFusionRankConstantAsInteger();
        if (searchers.length == 0) {
            logger.warn("searchWithMultipleSearchers called with empty searcher array");
            return createDegradedResponseList(params, params.getPageSize());
        }
        final int size = windowSize / searchers.length;
        if (logger.isDebugEnabled()) {
            logger.debug("Search parameters: windowSize={}, sizePerSearcher={}, rankConstant={}", windowSize, size, rankConstant);
        }
        final List<Future<SearchResult>> resultList = new ArrayList<>();
        for (int i = 0; i < searchers.length; i++) {
            final SearchRequestParams reqParams = new SearchRequestParamsWrapper(params, 0, i == 0 ? windowSize : size);
            final RankFusionSearcher searcher = searchers[i];
            resultList.add(executorService.submit(() -> {
                try {
                    if (externalContext != null) {
                        requestOpt.ifPresent(externalContext::setRequest);
                        responseOpt.ifPresent(externalContext::setResponse);
                    }
                    return searcher.search(query, reqParams, userBean);
                } finally {
                    if (externalContext != null) {
                        externalContext.setRequest(null);
                        externalContext.setResponse(null);
                    }
                }
            }));
        }
        final SearchResult[] results = resultList.stream().map(future -> {
            try {
                return future.get();
            } catch (final InterruptedException e) {
                logger.warn("Search operation was interrupted", e);
                Thread.currentThread().interrupt(); // Restore interrupt status
                return SearchResult.create().build();
            } catch (final ExecutionException e) {
                if (e.getCause() instanceof final InvalidQueryException iqe) {
                    throw iqe;
                }
                if (e.getCause() instanceof final ResultOffsetExceededException roee) {
                    throw roee;
                }
                if (e.getCause() instanceof final InvalidAccessTokenException iate) {
                    throw iate;
                }
                logger.warn("Search operation failed with exception", e.getCause());
                return SearchResult.create().build();
            }
        }).toArray(SearchResult[]::new);

        final String scoreField = fessConfig.getRankFusionScoreField();
        final Map<String, Map<String, Object>> documentsByIdMap = new HashMap<>();
        final String idField = fessConfig.getIndexFieldId();
        final Set<Object> mainSearcherIdSet = new HashSet<>();
        for (int searcherIndex = 0; searcherIndex < results.length; searcherIndex++) {
            final List<Map<String, Object>> docList = results[searcherIndex].getDocumentList();
            if (logger.isDebugEnabled()) {
                logger.debug("Searcher[{}]: retrieved {} documents / {} total documents", searcherIndex, docList.size(),
                        results[searcherIndex].getAllRecordCount());
            }
            for (int docRank = 0; docRank < docList.size(); docRank++) {
                final Map<String, Object> doc = docList.get(docRank);
                if (doc != null && doc.get(idField) instanceof final String id) {
                    // Calculate RRF score: 1 / (rank_constant + rank)
                    final float rrfScore = 1.0f / (rankConstant + docRank);
                    if (documentsByIdMap.containsKey(id)) {
                        final Map<String, Object> existingDoc = documentsByIdMap.get(id);
                        final float currentScore = toFloat(existingDoc.get(scoreField));
                        existingDoc.put(scoreField, currentScore + rrfScore);
                        // Merge searcher names
                        final String[] searcherNames = DocumentUtil.getValue(doc, Constants.SEARCHER, String[].class);
                        if (searcherNames != null) {
                            final String[] existingSearchers = DocumentUtil.getValue(existingDoc, Constants.SEARCHER, String[].class);
                            if (existingSearchers != null) {
                                existingDoc.put(Constants.SEARCHER, ArrayUtil.addAll(existingSearchers, searcherNames));
                            } else {
                                existingDoc.put(Constants.SEARCHER, searcherNames);
                            }
                        }
                    } else {
                        doc.put(scoreField, Float.valueOf(rrfScore));
                        documentsByIdMap.put(id, doc);
                    }
                    // Track documents from main searcher (index 0) within window size
                    if (searcherIndex == 0 && docRank < windowSize / 2) {
                        mainSearcherIdSet.add(id);
                    }
                }
            }
        }

        // Sort all documents by fused RRF score (descending)
        final var fusedDocs = documentsByIdMap.values()
                .stream()
                .sorted((doc1, doc2) -> Float.compare(toFloat(doc2.get(scoreField)), toFloat(doc1.get(scoreField))))
                .toList();

        // Calculate offset based on documents not in main searcher's top results
        int offset = 0;
        for (int i = 0; i < windowSize / 2 && i < fusedDocs.size(); i++) {
            if (!mainSearcherIdSet.contains(fusedDocs.get(i).get(idField))) {
                offset++;
            }
        }
        if (logger.isDebugEnabled()) {
            logger.debug("Calculated offset: {}, total fused documents: {}", offset, fusedDocs.size());
            final int logLimit = Math.min(10, fusedDocs.size());
            for (int i = 0; i < logLimit; i++) {
                final Map<String, Object> doc = fusedDocs.get(i);
                logger.debug("Fused rank[{}]: id={}, score={}", i, doc.get(idField), doc.get(scoreField));
            }
        }
        final SearchResult mainResult = results[0];
        long allRecordCount = mainResult.getAllRecordCount();
        if (Relation.EQUAL_TO.toString().equals(mainResult.getAllRecordCountRelation())) {
            allRecordCount += offset;
        }
        return createResponseList(extractList(fusedDocs, pageSize, startPosition), allRecordCount, mainResult.getAllRecordCountRelation(),
                mainResult.getQueryTime(), mainResult.isPartialResults(), mainResult.isTimedOut(), mainResult.isShardFailed(),
                mainResult.getFacetResponse(), startPosition, pageSize, offset);
    }

