public void handle(final HttpServletRequest req, final HttpServletResponse res) throws IOException {
        if (!"GET".equalsIgnoreCase(req.getMethod())) {
            res.setHeader("Allow", "GET");
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.METHOD_NOT_ALLOWED, "method not allowed");
            return;
        }
        try {
            final FessConfig cfg = ComponentUtil.getFessConfig();

            // Resolve the active theme via the registry; the registry may be unregistered
            // in some environments (notably stripped-down unit harnesses), so absence is
            // treated as "no theme" rather than an error.
            final Map<String, Object> themePayload = new LinkedHashMap<>();
            Optional<Theme> activeTheme = Optional.empty();
            try {
                final VirtualHostHelper vhost = ComponentUtil.getVirtualHostHelper();
                final String vhostKey = vhost == null ? null : vhost.getVirtualHostKey();
                final ThemeRegistry registry = ComponentUtil.getComponent(ThemeRegistry.class);
                if (registry != null) {
                    activeTheme = registry.resolveActiveTheme(vhostKey);
                    activeTheme.ifPresent(t -> {
                        themePayload.put("name", t.getName());
                        t.getManifest().ifPresent(m -> {
                            themePayload.put("display_name", m.getDisplayName());
                            themePayload.put("version", m.getVersion());
                            themePayload.put("supported_locales", m.getSupportedLocales());
                        });
                    });
                }
            } catch (final Exception themeEx) {
                logger.warn("Theme resolution failed; emitting empty theme payload", themeEx);
                // fall through with empty themePayload — the "theme" key is always present.
            }

            // Site name resolution: prefer the active theme manifest's display_name when
            // a theme is bound to the current request; otherwise fall back to the literal
            // "Fess". We intentionally do not introduce a new fess_config key here.
            final String siteName = activeTheme.flatMap(Theme::getManifest).map(ThemeManifest::getDisplayName).orElse("Fess");

            // Feature flags mirror what the legacy JSPs branch on so the SPA can light up
            // the same set of UI affordances without round-tripping more endpoints.
            final boolean searchLogEnabled = cfg.isSearchLog();
            final boolean userFavoriteEnabled = cfg.isUserFavorite();
            final boolean thumbnailEnabled = cfg.isThumbnailEnabled();

            // eoled comes from SystemHelper, the same source as the JSP runtime data.
            boolean eoled = false;
            try {
                final SystemHelper systemHelper = ComponentUtil.getSystemHelper();
                if (systemHelper != null) {
                    eoled = systemHelper.isEoled();
                }
            } catch (final Exception ignored) {
                // SystemHelper not wired in unit harness — default to false.
            }
            // development_mode reported whether Fess was running the embedded search engine, which
            // no longer exists: the search engine is always a separate server now. The field is
            // required by openapi-user.yaml and read by the bundled theme, so it stays and is false.
            final boolean developmentMode = false;

            // label_options: built from LabelTypeHelper; empty list when no labels configured.
            final List<Map<String, Object>> labelOptions = new ArrayList<>();
            try {
                final LabelTypeHelper labelTypeHelper = ComponentUtil.getLabelTypeHelper();
                if (labelTypeHelper != null) {
                    final List<Map<String, String>> items = labelTypeHelper.getLabelTypeItemList(SearchRequestType.JSON, Locale.ROOT);
                    if (items != null) {
                        for (final Map<String, String> item : items) {
                            final Map<String, Object> entry = new LinkedHashMap<>();
                            entry.put("value", item.get(Constants.ITEM_VALUE));
                            entry.put("name", item.get(Constants.ITEM_LABEL));
                            labelOptions.add(entry);
                        }
                    }
                }
            } catch (final Exception ignored) {
                // LabelTypeHelper not wired — return empty list.
            }

            // eol_link / installation_link — surfaced as resolved URLs. Derivation mirrors
            // the JSP runtime data registered by SystemHelper (setupSearchHtmlData /
            // setupAdminHtmlData): the installation link resolves the online.help.installation
            // template and the EOL link resolves the online.help.eol template, both via the
            // shared SystemHelper#getHelpUrl locale/version substitution.
            // Falls back to empty string when SystemHelper / RequestManager are unavailable.
            String eolLink = "";
            String installationLink = "";
            try {
                final SystemHelper systemHelper = ComponentUtil.getSystemHelper();
                if (systemHelper != null) {
                    try {
                        installationLink = systemHelper.getInstallationLink();
                    } catch (final Exception ignored) {
                        // RequestManager not bound in unit harness — leave empty.
                    }
                    if (eoled) {
                        try {
                            eolLink = systemHelper.getEolLink();
                        } catch (final Exception ignored) {
                            // RequestManager not bound in unit harness — leave empty.
                        }
                    }
                }
            } catch (final Exception ignored) {
                // SystemHelper not wired in unit harness — default to empty strings.
            }

            // login_link: mirrors fessConfig.isLoginLinkEnabled() used by JSP pageLoginLink.
            boolean loginLinkEnabled = true;
            try {
                loginLinkEnabled = cfg.isLoginLinkEnabled();
            } catch (final Exception ignored) {
                // FessProp system-property store not accessible — default to true.
            }

            final Map<String, Object> features = new LinkedHashMap<>();
            features.put("user_favorite", userFavoriteEnabled);
            features.put("popular_word", cfg.isWebApiPopularWord());
            features.put("suggest_search_log", cfg.isSuggestSearchLog());
            features.put("suggest_documents", cfg.isSuggestDocuments());
            features.put("login_required", cfg.isLoginRequired());
            features.put("eoled", eoled);
            features.put("development_mode", developmentMode);
            features.put("search_log_enabled", searchLogEnabled);
            features.put("thumbnail_enabled", thumbnailEnabled);
            features.put("display_label_type", !labelOptions.isEmpty());
            // A.4: clipboard copy icon toggle (mirrors view.copy.icon.enabled / clipboard.copy.icon.enabled).
            features.put("clipboard_copy_icon", cfg.isClipboardCopyIconEnabled());
            // B.1: EOL and installation links (may be empty strings when not applicable).
            features.put("eol_link", eolLink);
            features.put("installation_link", installationLink);
            // B.2: login link availability flag.
            features.put("login_link", loginLinkEnabled);
            // rag_chat_enabled: mirrors FessSearchAction#setupHtmlData chatClient.isAvailable()
            // so the static-theme SPA sees the same availability gate as the legacy JSP path.
            boolean ragChatEnabled = false;
            try {
                final ChatClient chatClient = ComponentUtil.getComponent(ChatClient.class);
                if (chatClient != null) {
                    ragChatEnabled = chatClient.isAvailable();
                }
            } catch (final Exception ignored) {
                // ChatClient not wired in unit harness — default to false.
            }
            features.put("rag_chat_enabled", ragChatEnabled);

            // Server-wide supported language list, surfaced as plain JSON array of codes.
            final String[] langs = cfg.getSupportedLanguagesAsArray();

            // The CSRF token is always required for v2 state-changing requests, so the SPA
            // MUST include the X-Fess-CSRF-Token header. The csrf_required/csrf_token fields
            // are retained for SPA backward compatibility; csrf_required is now always true
            // and a freshly-issued session-bound token is always returned. Using
            // getSession(true) ensures the session exists even on the very first request.
            final HttpSession session = req.getSession(true);
            final SessionCsrfTokenManager csrf = ComponentUtil.getComponent(SessionCsrfTokenManager.class);
            final String csrfToken = csrf == null ? "" : csrf.issue(session);

            // sort_options: conditionally include click_count and favorite_count entries.
            final List<Map<String, Object>> sortOptions = buildSortOptions(searchLogEnabled, userFavoriteEnabled);

            // num_options: filter out values exceeding page_size_max.
            final int pageMax = cfg.getPagingSearchPageMaxSizeAsInteger();
            final List<Integer> numOptions = new ArrayList<>();
            for (final int n : new int[] { 10, 20, 30, 40, 50, 100 }) {
                if (n <= pageMax) {
                    numOptions.add(n);
                }
            }

            // lang_options: "all" sentinel + supported language codes.
            final List<Map<String, Object>> langOptions = new ArrayList<>();
            final Map<String, Object> allLang = new LinkedHashMap<>();
            allLang.put("value", "all");
            allLang.put("label_key", "labels.searchoptions_all_langs");
            langOptions.add(allLang);
            if (langs != null) {
                for (final String lang : langs) {
                    if (lang != null && !lang.isEmpty()) {
                        final Map<String, Object> langEntry = new LinkedHashMap<>();
                        langEntry.put("value", lang);
                        langEntry.put("label_key", "labels.lang_" + lang);
                        langOptions.add(langEntry);
                    }
                }
            }

            // notifications: HTML snippets shown at the top of specific views.
            // Values come from the system-property store (configurable via admin UI).
            // Empty string means "no notification for this view".
            final Map<String, Object> notifications = new LinkedHashMap<>();
            notifications.put("search_top", cfg.getNotificationSearchTop());
            notifications.put("advance_search", cfg.getNotificationAdvanceSearch());
            notifications.put("login", cfg.getNotificationLogin());

            // B.3: facet_views — ordered list of FacetQueryView group descriptors from ViewHelper.
            // Each entry: {group_name: String, queries: [{label_key: String, value: String}]}
            // Falls back to an empty list when ViewHelper is not wired (unit harness / stripped env).
            final List<Map<String, Object>> facetViews = new ArrayList<>();
            try {
                final ViewHelper viewHelper = ComponentUtil.getViewHelper();
                if (viewHelper != null) {
                    for (final FacetQueryView fqv : viewHelper.getFacetQueryViewList()) {
                        final Map<String, Object> group = new LinkedHashMap<>();
                        group.put("group_name", fqv.getTitle() != null ? fqv.getTitle() : "");
                        final List<Map<String, Object>> queries = new ArrayList<>();
                        if (fqv.getQueryMap() != null) {
                            fqv.getQueryMap().forEach((labelKey, queryValue) -> {
                                final Map<String, Object> q = new LinkedHashMap<>();
                                q.put("label_key", labelKey);
                                q.put("value", queryValue);
                                queries.add(q);
                            });
                        }
                        group.put("queries", queries);
                        facetViews.add(group);
                    }
                }
            } catch (final Exception ignored) {
                // ViewHelper not wired in stripped unit harness — emit empty list.
            }

            final Map<String, Object> payload = new LinkedHashMap<>();
            payload.put("site_name", siteName);
            payload.put("login_required", cfg.isLoginRequired());
            payload.put("locales", langs == null ? java.util.List.of() : Arrays.asList(langs));
            payload.put("theme", themePayload);
            payload.put("features", features);
            payload.put("page_size_default", cfg.getPagingSearchPageSizeAsInteger());
            payload.put("page_size_max", pageMax);
            payload.put("sort_options", sortOptions);
            payload.put("num_options", numOptions);
            payload.put("lang_options", langOptions);
            payload.put("label_options", labelOptions);
            payload.put("notifications", notifications);
            payload.put("facet_views", facetViews);
            payload.put("filetype_options", buildFiletypeOptions());
            payload.put("csrf_required", true);
            payload.put("csrf_token", csrfToken);
            ComponentUtil.getV2EnvelopeWriter().writeSuccess(res, payload);
        } catch (final Exception e) {
            ComponentUtil.getV2EnvelopeWriter().writeInternalError(res, e, logger, "/api/v2/ui/config");
        }
    }

protected void executeCrawler() {
        final List<String> cmdList = new ArrayList<>();
        final String cpSeparator = SystemUtils.IS_OS_WINDOWS ? ";" : ":";
        final ServletContext servletContext = ComponentUtil.getComponent(ServletContext.class);
        final SystemHelper systemHelper = ComponentUtil.getSystemHelper();
        final ProcessHelper processHelper = ComponentUtil.getProcessHelper();
        final FessConfig fessConfig = ComponentUtil.getFessConfig();

        cmdList.add(fessConfig.getJavaCommandPath());

        // -cp
        cmdList.add("-cp");
        final StringBuilder buf = new StringBuilder(100);
        ResourceUtil.getOverrideConfPath().ifPresent(p -> {
            buf.append(p);
            buf.append(cpSeparator);
        });
        final String confPath = System.getProperty(Constants.FESS_CONF_PATH);
        if (StringUtil.isNotBlank(confPath)) {
            buf.append(confPath);
            buf.append(cpSeparator);
        }
        // WEB-INF/env/crawler/resources
        buf.append("WEB-INF");
        buf.append(File.separator);
        buf.append("env");
        buf.append(File.separator);
        buf.append(getExecuteType());
        buf.append(File.separator);
        buf.append("resources");
        buf.append(cpSeparator);
        // WEB-INF/classes
        buf.append("WEB-INF");
        buf.append(File.separator);
        buf.append("classes");
        // target/classes
        final String userDir = System.getProperty("user.dir");
        final File targetDir = new File(userDir, "target");
        final File targetClassesDir = new File(targetDir, "classes");
        if (targetClassesDir.isDirectory()) {
            buf.append(cpSeparator);
            buf.append(targetClassesDir.getAbsolutePath());
        }
        // WEB-INF/lib
        appendJarFile(cpSeparator, buf, new File(servletContext.getRealPath("/WEB-INF/lib")),
                "WEB-INF" + File.separator + "lib" + File.separator);
        // WEB-INF/env/crawler/lib
        appendJarFile(cpSeparator, buf, new File(servletContext.getRealPath("/WEB-INF/env/" + getExecuteType() + "/lib")),
                "WEB-INF" + File.separator + "env" + File.separator + getExecuteType() + File.separator + "lib" + File.separator);
        // WEB-INF/plugin
        appendJarFile(cpSeparator, buf, new File(servletContext.getRealPath("/WEB-INF/plugin")),
                "WEB-INF" + File.separator + "plugin" + File.separator);
        final File targetLibDir = new File(targetDir, "fess" + File.separator + "WEB-INF" + File.separator + "lib");
        if (targetLibDir.isDirectory()) {
            appendJarFile(cpSeparator, buf, targetLibDir, targetLibDir.getAbsolutePath() + File.separator);
        }
        cmdList.add(buf.toString());

        if (useLocalFesen) {
            final String httpAddress = SystemUtil.getSearchEngineHttpAddress();
            if (StringUtil.isNotBlank(httpAddress)) {
                cmdList.add("-D" + Constants.FESS_SEARCH_ENGINE_HTTP_ADDRESS + "=" + httpAddress);
            }
        }

        final String systemLastaEnv = System.getProperty("lasta.env");
        if (StringUtil.isNotBlank(systemLastaEnv)) {
            if ("web".equals(systemLastaEnv)) {
                cmdList.add("-Dlasta.env=" + getExecuteType());
            } else {
                cmdList.add("-Dlasta.env=" + systemLastaEnv);
            }
        } else if (StringUtil.isNotBlank(lastaEnv)) {
            cmdList.add("-Dlasta.env=" + lastaEnv);
        } else {
            cmdList.add("-Dlasta.env=" + getExecuteType());
        }

        addFessConfigProperties(cmdList);
        addFessSystemProperties(cmdList);
        addFessCustomSystemProperties(cmdList, fessConfig.getJobSystemPropertyFilterPattern());
        addSystemProperty(cmdList, Constants.FESS_CONF_PATH, null, null);
        addSystemProperty(cmdList, Constants.FESS_HOME, null, null);
        cmdList.add("-Dfess." + getExecuteType() + ".process=true");
        cmdList.add("-Dfess.log.path=" + (logFilePath != null ? logFilePath : systemHelper.getLogFilePath()));
        addSystemProperty(cmdList, "fess.log.name", getLogName("fess"), getLogName(StringUtil.EMPTY));
        if (logLevel == null) {
            addSystemProperty(cmdList, "fess.log.level", null, null);
        } else {
            cmdList.add("-Dfess.log.level=" + logLevel);
            if ("debug".equalsIgnoreCase(logLevel)) {
                cmdList.add("-Dorg.apache.tika.service.error.warn=true");
            }
        }
        stream(fessConfig.getJvmCrawlerOptionsAsArray())
                .of(stream -> stream.filter(StringUtil::isNotBlank).forEach(value -> cmdList.add(value)));

        File ownTmpDir = null;
        final String tmpDir = System.getProperty("java.io.tmpdir");
        if (fessConfig.isUseOwnTmpDir() && StringUtil.isNotBlank(tmpDir)) {
            ownTmpDir = new File(tmpDir, "fessTmpDir_" + sessionId);
            if (ownTmpDir.mkdirs()) {
                cmdList.add("-Djava.io.tmpdir=" + ownTmpDir.getAbsolutePath());
                cmdList.add("-Dpdfbox.fontcache=" + ownTmpDir.getAbsolutePath());
            } else {
                ownTmpDir = null;
            }
        }

        cmdList.add(ComponentUtil.getThumbnailManager().getThumbnailPathOption());

        if (!jvmOptions.isEmpty()) {
            jvmOptions.stream().filter(StringUtil::isNotBlank).forEach(cmdList::add);
        }

        cmdList.add(Crawler.class.getCanonicalName());

        cmdList.add("--sessionId");
        cmdList.add(sessionId);
        cmdList.add("--name");
        cmdList.add(namespace);

        if (webConfigIds != null && webConfigIds.length > 0) {
            cmdList.add("-w");
            cmdList.add(StringUtils.join(webConfigIds, ','));
        }
        if (fileConfigIds != null && fileConfigIds.length > 0) {
            cmdList.add("-f");
            cmdList.add(StringUtils.join(fileConfigIds, ','));
        }
        if (dataConfigIds != null && dataConfigIds.length > 0) {
            cmdList.add("-d");
            cmdList.add(StringUtils.join(dataConfigIds, ','));
        }
        if (documentExpires >= -1) {
            cmdList.add("-e");
            cmdList.add(Integer.toString(documentExpires));
        }
        if (hotThreadInterval > -1) {
            cmdList.add("-h");
            cmdList.add(Integer.toString(hotThreadInterval));
        }

        final File propFile = ComponentUtil.getSystemHelper().createTempFile(getExecuteType() + "_", ".properties");
        try {
            cmdList.add("-p");
            cmdList.add(propFile.getAbsolutePath());
            createSystemProperties(cmdList, propFile);

            final File baseDir = new File(servletContext.getRealPath("/WEB-INF")).getParentFile();

            if (logger.isInfoEnabled()) {
                logger.info("Crawler: \nDirectory={}\nOptions={}", baseDir, cmdList);
            }

            final JobProcess jobProcess = processHelper.startProcess(sessionId, cmdList, pb -> {
                pb.directory(baseDir);
                pb.redirectErrorStream(true);
            });

            final InputStreamThread it = jobProcess.getInputStreamThread();
            it.start();

            final Process currentProcess = jobProcess.getProcess();
            currentProcess.waitFor();
            it.join(5000);

            final int exitValue = currentProcess.exitValue();

            if (logger.isInfoEnabled()) {
                logger.info("Crawler: Exit Code={} - Process Output:\n{}", exitValue, it.getOutput());
            }
            if (exitValue != 0) {
                final StringBuilder out = new StringBuilder();
                if (processTimeout) {
                    out.append("Process is terminated due to ").append(timeout).append(" second exceeded.\n");
                }
                out.append("Exit Code: ").append(exitValue).append("\nOutput:\n").append(it.getOutput());
                throw new JobProcessingException(out.toString());
            }
        } catch (final JobProcessingException e) {
            throw e;
        } catch (final Exception e) {
            throw new JobProcessingException("Crawler Process terminated.", e);
        } finally {
            try {
                processHelper.destroyProcess(sessionId);
            } finally {
                if (propFile != null && !propFile.delete()) {
                    logger.warn("Failed to delete properties file: {}", propFile.getAbsolutePath());
                }
                deleteTempDir(ownTmpDir);
            }
        }
    }

@Override
    public CrawlerClientFactory initializeClientFactory(final Supplier<CrawlerClientFactory> creator) {
        if (crawlerClientFactory != null) {
            return crawlerClientFactory;
        }
        final CrawlerClientFactory factory = creator.get();

        final Map<String, String> paramMap = getHandlerParameterMap();

        final Map<String, Object> factoryParamMap = new HashMap<>();
        factory.setInitParameterMap(factoryParamMap);

        // parameters
        for (final Map.Entry<String, String> entry : paramMap.entrySet()) {
            final String key = entry.getKey();
            if (key.startsWith(CRAWLER_PARAM_PREFIX)) {
                factoryParamMap.put(key.substring(CRAWLER_PARAM_PREFIX.length()), entry.getValue());
            }
        }

        // user agent
        final String userAgent = paramMap.get(CRAWLER_USERAGENT);
        if (StringUtil.isNotBlank(userAgent)) {
            factoryParamMap.put(HcHttpClient.USER_AGENT_PROPERTY, userAgent);
        }

        // web auth
        final String webAuthStr = paramMap.get(CRAWLER_WEB_AUTH);
        if (StringUtil.isNotBlank(webAuthStr)) {
            final String[] webAuthNames = webAuthStr.split(",");
            final List<WebAuthenticationConfig> authConfigList = new ArrayList<>();
            for (final String webAuthName : webAuthNames) {
                authConfigList.add(createWebAuthConfig(paramMap, webAuthName));
            }
            factoryParamMap.put(HcHttpClient.AUTHENTICATIONS_PROPERTY,
                    authConfigList.toArray(new WebAuthenticationConfig[authConfigList.size()]));
        }

        // request header
        final List<org.codelibs.fess.crawler.client.http.RequestHeader> rhList = new ArrayList<>();
        int count = 1;
        String headerName = paramMap.get(CRAWLER_WEB_HEADER_PREFIX + count + ".name");
        while (StringUtil.isNotBlank(headerName)) {
            final String headerValue = paramMap.get(CRAWLER_WEB_HEADER_PREFIX + count + ".value");
            rhList.add(new org.codelibs.fess.crawler.client.http.RequestHeader(headerName, headerValue));
            count++;
            headerName = paramMap.get(CRAWLER_WEB_HEADER_PREFIX + count + ".name");
        }
        if (!rhList.isEmpty()) {
            factoryParamMap.put(HcHttpClient.REQUEST_HEADERS_PROPERTY,
                    rhList.toArray(new org.codelibs.fess.crawler.client.http.RequestHeader[rhList.size()]));
        }

        // proxy credentials
        final String proxyHost = paramMap.get(CRAWLER_WEB_PREFIX + "proxyHost");
        final String proxyPort = paramMap.get(CRAWLER_WEB_PREFIX + "proxyPort");
        if (StringUtil.isNotBlank(proxyHost) && StringUtil.isNotBlank(proxyPort)) {
            factoryParamMap.put(HcHttpClient.PROXY_HOST_PROPERTY, proxyHost);
            factoryParamMap.put(HcHttpClient.PROXY_PORT_PROPERTY, proxyPort);
            final String proxyUsername = paramMap.get(CRAWLER_WEB_PREFIX + "proxyUsername");
            final String proxyPassword = paramMap.get(CRAWLER_WEB_PREFIX + "proxyPassword");
            if (proxyUsername != null && proxyPassword != null) {
                factoryParamMap.put(HcHttpClient.PROXY_CREDENTIALS_PROPERTY,
                        CrawlingConfig.createProxyCredentials(proxyUsername, proxyPassword));
            }
        } else {
            initializeDefaultHttpProxy(factoryParamMap);
        }

        // file auth
        final String fileAuthStr = paramMap.get(CRAWLER_FILE_AUTH);
        if (StringUtil.isNotBlank(fileAuthStr)) {
            final String[] fileAuthNames = fileAuthStr.split(",");
            final List<SmbAuthentication> smbAuthList = new ArrayList<>();
            final List<org.codelibs.fess.crawler.client.smb1.SmbAuthentication> smb1AuthList = new ArrayList<>();
            final List<FtpAuthentication> ftpAuthList = new ArrayList<>();
            for (final String fileAuthName : fileAuthNames) {
                final String scheme = paramMap.get(CRAWLER_FILE_AUTH + "." + fileAuthName + ".scheme");
                if (Constants.SAMBA.equals(scheme)) {
                    final String domain = paramMap.get(CRAWLER_FILE_AUTH + "." + fileAuthName + ".domain");
                    final String hostname = paramMap.get(CRAWLER_FILE_AUTH + "." + fileAuthName + ".host");
                    final String port = paramMap.get(CRAWLER_FILE_AUTH + "." + fileAuthName + ".port");
                    final String username = paramMap.get(CRAWLER_FILE_AUTH + "." + fileAuthName + ".username");
                    final String password = paramMap.get(CRAWLER_FILE_AUTH + "." + fileAuthName + ".password");

                    if (StringUtil.isEmpty(username)) {
                        logger.warn("username is empty. fileAuth:{}", fileAuthName);
                        continue;
                    }

                    final SmbAuthentication smbAuth = new SmbAuthentication();
                    smbAuth.setDomain(domain == null ? StringUtil.EMPTY : domain);
                    smbAuth.setServer(hostname);
                    if (StringUtil.isNotBlank(port)) {
                        try {
                            smbAuth.setPort(Integer.parseInt(port));
                        } catch (final NumberFormatException e) {
                            logger.warn("Failed to parse {}", port, e);
                        }
                    }
                    smbAuth.setUsername(username);
                    smbAuth.setPassword(password == null ? StringUtil.EMPTY : password);
                    smbAuthList.add(smbAuth);

                    final org.codelibs.fess.crawler.client.smb1.SmbAuthentication smb1Auth =
                            new org.codelibs.fess.crawler.client.smb1.SmbAuthentication();
                    smb1Auth.setDomain(domain == null ? StringUtil.EMPTY : domain);
                    smb1Auth.setServer(hostname);
                    if (StringUtil.isNotBlank(port)) {
                        try {
                            smb1Auth.setPort(Integer.parseInt(port));
                        } catch (final NumberFormatException e) {
                            logger.warn("Failed to parse {}", port, e);
                        }
                    }
                    smb1Auth.setUsername(username);
                    smb1Auth.setPassword(password == null ? StringUtil.EMPTY : password);
                    smb1AuthList.add(smb1Auth);
                } else if (Constants.FTP.equals(scheme)) {
                    final String hostname = paramMap.get(CRAWLER_FILE_AUTH + "." + fileAuthName + ".host");
                    final String port = paramMap.get(CRAWLER_FILE_AUTH + "." + fileAuthName + ".port");
                    final String username = paramMap.get(CRAWLER_FILE_AUTH + "." + fileAuthName + ".username");
                    final String password = paramMap.get(CRAWLER_FILE_AUTH + "." + fileAuthName + ".password");

                    if (StringUtil.isEmpty(username)) {
                        logger.warn("username is empty. fileAuth:{}", fileAuthName);
                        continue;
                    }

                    final FtpAuthentication ftpAuth = new FtpAuthentication();
                    ftpAuth.setServer(hostname);
                    if (StringUtil.isNotBlank(port)) {
                        try {
                            ftpAuth.setPort(Integer.parseInt(port));
                        } catch (final NumberFormatException e) {
                            logger.warn("Failed to parse {}", port, e);
                        }
                    }
                    ftpAuth.setUsername(username);
                    ftpAuth.setPassword(password == null ? StringUtil.EMPTY : password);
                    ftpAuthList.add(ftpAuth);
                }
            }
            if (!smbAuthList.isEmpty()) {
                factoryParamMap.put(SmbClient.SMB_AUTHENTICATIONS_PROPERTY, smbAuthList.toArray(new SmbAuthentication[smbAuthList.size()]));
            }
            if (!smb1AuthList.isEmpty()) {
                factoryParamMap.put(org.codelibs.fess.crawler.client.smb1.SmbClient.SMB_AUTHENTICATIONS_PROPERTY,
                        smb1AuthList.toArray(new org.codelibs.fess.crawler.client.smb1.SmbAuthentication[smb1AuthList.size()]));
            }
            if (!ftpAuthList.isEmpty()) {
                factoryParamMap.put(FtpClient.FTP_AUTHENTICATIONS_PROPERTY, ftpAuthList.toArray(new FtpAuthentication[ftpAuthList.size()]));
            }
        }

        crawlerClientFactory = factory;
        return factory;
    }

@Override
    public void run() {
        if (dataService == null) {
            throw new FessSystemException("DataService is null. IndexUpdater cannot proceed without a DataService instance.");
        }

        if (logger.isDebugEnabled()) {
            logger.debug("Starting indexUpdater.");
        }

        executeTime = 0;
        documentSize = 0;

        final FessConfig fessConfig = ComponentUtil.getFessConfig();
        final long updateInterval = fessConfig.getIndexerWebfsUpdateIntervalAsInteger().longValue();
        final int maxEmptyListCount = fessConfig.getIndexerWebfsMaxEmptyListCountAsInteger();
        final IntervalControlHelper intervalControlHelper = ComponentUtil.getIntervalControlHelper();
        try {
            final Consumer<SearchRequestBuilder> cb = builder -> {
                final QueryBuilder queryBuilder = QueryBuilders.boolQuery()
                        .filter(QueryBuilders.termsQuery(OpenSearchAccessResult.SESSION_ID, sessionIdList))
                        .filter(QueryBuilders.termQuery(OpenSearchAccessResult.STATUS, org.codelibs.fess.crawler.Constants.OK_STATUS));
                builder.setQuery(queryBuilder);
                builder.setFrom(0);
                final int maxDocumentCacheSize = fessConfig.getIndexerWebfsMaxDocumentCacheSizeAsInteger();
                builder.setSize(maxDocumentCacheSize <= 0 ? 1 : maxDocumentCacheSize);
                builder.addSort(OpenSearchAccessResult.CREATE_TIME, SortOrder.ASC);
            };

            final DocList docList = new DocList();
            final List<OpenSearchAccessResult> accessResultList = new ArrayList<>();

            long updateTime = systemHelper.getCurrentTimeAsLong();
            int errorCount = 0;
            int emptyListCount = 0;
            long cleanupTime = -1;
            while (!finishCrawling || !accessResultList.isEmpty()) {
                try {
                    final int sessionIdListSize = finishedSessionIdList.size();
                    intervalControlHelper.setCrawlerRunning(true);

                    docList.clear();
                    accessResultList.clear();

                    updateTime = systemHelper.getCurrentTimeAsLong() - updateTime;

                    final long interval = updateInterval - updateTime;
                    if (interval > 0) {
                        // sleep
                        ThreadUtil.sleep(interval); // 10 sec (default)
                    }

                    systemHelper.calibrateCpuLoad();
                    systemHelper.waitForNoWaitingThreads();

                    intervalControlHelper.delayByRules();

                    if (logger.isDebugEnabled()) {
                        logger.debug("Processing documents in IndexUpdater queue.");
                    }

                    updateTime = systemHelper.getCurrentTimeAsLong();

                    List<OpenSearchAccessResult> arList = getAccessResultList(cb, cleanupTime);
                    if (arList.isEmpty()) {
                        emptyListCount++;
                    } else {
                        emptyListCount = 0; // reset
                    }
                    long hitCount = ((OpenSearchResultList<OpenSearchAccessResult>) arList).getTotalHits();
                    while (hitCount > 0) {
                        if (arList.isEmpty()) {
                            ThreadUtil.sleep(fessConfig.getIndexerWebfsCommitMarginTimeAsInteger().longValue());
                            cleanupTime = -1;
                        } else {
                            processAccessResults(docList, accessResultList, arList);
                            cleanupTime = cleanupAccessResults(accessResultList);
                        }
                        arList = getAccessResultList(cb, cleanupTime);
                        hitCount = ((OpenSearchResultList<OpenSearchAccessResult>) arList).getTotalHits();
                    }
                    if (!docList.isEmpty()) {
                        indexingHelper.sendDocuments(searchEngineClient, docList);
                    }

                    synchronized (finishedSessionIdList) {
                        if (sessionIdListSize != 0 && sessionIdListSize == finishedSessionIdList.size()) {
                            cleanupFinishedSessionData();
                        }
                    }
                    executeTime += systemHelper.getCurrentTimeAsLong() - updateTime;

                    if (logger.isDebugEnabled()) {
                        logger.debug("Processed documents in IndexUpdater queue.");
                    }

                    // reset count
                    errorCount = 0;
                } catch (final Exception e) {
                    if (errorCount > maxErrorCount) {
                        throw e;
                    }
                    errorCount++;
                    logger.warn("Failed to access AccessResult data. Retrying... (attempt={}/{})", errorCount, maxErrorCount, e);
                } finally {
                    if (systemHelper.isForceStop()) {
                        finishCrawling = true;
                        if (logger.isDebugEnabled()) {
                            logger.debug("Stopped indexUpdater.");
                        }
                    }
                }

                if (emptyListCount >= maxEmptyListCount) {
                    if (logger.isInfoEnabled()) {
                        logger.info("Terminating indexUpdater. emptyListCount is over {}.", maxEmptyListCount);
                    }
                    // terminate crawling
                    finishCrawling = true;
                    forceStop();
                    if (fessConfig.getIndexerThreadDumpEnabledAsBoolean()) {
                        ThreadDumpUtil.printThreadDump();
                    }
                    org.codelibs.fess.exec.Crawler.addError("QueueTimeout");
                }

                if (!ComponentUtil.available()) {
                    logger.info("IndexUpdater is terminated.");
                    forceStop();
                    break;
                }
            }

            if (logger.isDebugEnabled()) {
                logger.debug("Finished indexUpdater.");
            }
        } catch (final ContainerNotAvailableException e) {
            if (logger.isDebugEnabled()) {
                logger.debug("IndexUpdater is terminated.", e);
            } else if (logger.isInfoEnabled()) {
                logger.info("IndexUpdater is terminated.");
            }
            forceStop();
        } catch (final Throwable t) {
            if (ComponentUtil.available()) {
                logger.error("IndexUpdater is terminated.", t);
            } else if (logger.isDebugEnabled()) {
                logger.debug("IndexUpdater is terminated.", t);
                org.codelibs.fess.exec.Crawler.addError(t.getClass().getSimpleName());
            } else if (logger.isInfoEnabled()) {
                logger.info("IndexUpdater is terminated.");
                org.codelibs.fess.exec.Crawler.addError(t.getClass().getSimpleName());
            }
            forceStop();
        } finally {
            intervalControlHelper.setCrawlerRunning(true);
        }

        if (logger.isInfoEnabled()) {
            logger.info("[EXEC TIME] index update time: {}ms", executeTime);
        }

    }

