public void handle(final HttpServletRequest req, final HttpServletResponse res) throws IOException {
        if (!"POST".equalsIgnoreCase(req.getMethod())) {
            res.setHeader("Allow", "POST");
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.METHOD_NOT_ALLOWED, "method not allowed");
            return;
        }
        final FessConfig cfg = ComponentUtil.getFessConfig();
        if (!cfg.isSearchLog()) {
            // Feature disabled — succeed without doing anything (fire-and-forget contract).
            ComponentUtil.getV2EnvelopeWriter().writeSuccess(res, Map.of("ok", true, "logged", false));
            return;
        }
        // m-15: check session BEFORE parsing the body so anonymous callers short-circuit
        // immediately and malformed-body errors are not reported for anonymous requests.
        // Defensive against missing UserInfoHelper in slim test DI graphs — treat as anonymous.
        String userSessionId = null;
        try {
            userSessionId = ComponentUtil.getUserInfoHelper().getUserCode();
        } catch (final RuntimeException e) {
            // UserInfoHelper unavailable (e.g. unit harness): behave as anonymous.
            // Promote to WARN exactly once per JVM so an accidental misconfiguration
            // in production (e.g. component removed from DI graph) is surfaced
            // without flooding logs on every click.
            if (userInfoHelperWarned.compareAndSet(false, true)) {
                logger.warn("UserInfoHelper unavailable; treating click as anonymous", e);
            }
        }
        if (userSessionId == null) {
            // Anonymous caller: a click log without a session id is meaningless,
            // so report success with logged:false rather than failing the request.
            ComponentUtil.getV2EnvelopeWriter().writeSuccess(res, Map.of("ok", true, "logged", false));
            return;
        }
        final Map<String, Object> body;
        try {
            body = ComponentUtil.getV2JsonBody().read(req, MAX_BODY_BYTES);
        } catch (final V2JsonBody.PayloadTooLargeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.PAYLOAD_TOO_LARGE, e.getMessage());
            return;
        } catch (final V2JsonBody.UnsupportedMediaTypeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.UNSUPPORTED_MEDIA_TYPE, e.getMessage());
            return;
        } catch (final V2JsonBody.MalformedJsonException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, e.getMessage());
            return;
        }
        final String docId = stringOrNull(body, "doc_id");
        final String queryId = stringOrNull(body, "query_id");
        if (!ComponentUtil.getV2DocIdValidator().isValid(docId)) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "invalid doc_id");
            return;
        }
        if (queryId != null) {
            if (queryId.length() > QUERY_ID_MAX_LENGTH) {
                ComponentUtil.getV2EnvelopeWriter()
                        .writeError(res, V2ErrorCode.INVALID_REQUEST, "query_id exceeds the maximum length of " + QUERY_ID_MAX_LENGTH);
                return;
            }
            if (!QUERY_ID_PATTERN.matcher(queryId).matches()) {
                ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "query_id contains invalid characters");
                return;
            }
        }
        final Object rt = body.get("rt");
        final Object rank = body.get("rank");
        if (rt instanceof Number && ((Number) rt).longValue() < 0) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "rt must not be negative");
            return;
        }
        if (rt instanceof Number && ((Number) rt).longValue() > cfg.getApiClickMaxTimestampOrDefault()) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "rt exceeds the maximum");
            return;
        }
        if (rank instanceof Number && ((Number) rank).intValue() < 0) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "rank must not be negative");
            return;
        }
        // rank upper-bound guard (L-5): evaluate as long to also catch int-overflow values.
        if (rank instanceof Number && ((Number) rank).longValue() > MAX_RANK) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "rank exceeds the maximum");
            return;
        }
        // query_id membership (L-5, best-effort): only reject a provable mismatch; skip when the
        // per-session result set is unknown/empty so logging is never broken in default deployments.
        if (StringUtil.isNotBlank(queryId)) {
            String[] resultDocIds;
            try {
                resultDocIds = ComponentUtil.getUserInfoHelper().getResultDocIds(queryId);
            } catch (final RuntimeException e) {
                resultDocIds = null; // unverifiable; do not break logging
            }
            if (resultDocIds != null && resultDocIds.length > 0 && !ArrayUtils.contains(resultDocIds, docId)) {
                ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.NOT_FOUND, "doc not in search result");
                return;
            }
        }
        try {
            final SearchHelper searchHelper = ComponentUtil.getSearchHelper();
            final OptionalEntity<Map<String, Object>> docOpt = searchHelper.getDocumentByDocId(docId,
                    new String[] { cfg.getIndexFieldId(), cfg.getIndexFieldUrl() }, OptionalThing.empty());
            if (!docOpt.isPresent()) {
                ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.NOT_FOUND, "doc not found: " + docId);
                return;
            }
            final Map<String, Object> doc = docOpt.get();
            final String url = DocumentUtil.getValue(doc, cfg.getIndexFieldUrl(), String.class);
            final SystemHelper systemHelper = ComponentUtil.getSystemHelper();
            final ClickLog clickLog = new ClickLog();
            clickLog.setUrlId((String) doc.get(cfg.getIndexFieldId()));
            clickLog.setUrl(url);
            clickLog.setRequestedAt(systemHelper.getCurrentTimeAsLocalDateTime());
            if (rt instanceof Number) {
                // m-8: use UTC so the same epoch-ms yields the same LocalDateTime regardless of
                // host timezone; click logs are stored consistently across mixed-TZ clusters.
                clickLog.setQueryRequestedAt(epochMsToUtcLocalDateTime(((Number) rt).longValue()));
            } else {
                clickLog.setQueryRequestedAt(systemHelper.getCurrentTimeAsLocalDateTime());
            }
            clickLog.setUserSessionId(userSessionId);
            clickLog.setDocId(docId);
            clickLog.setQueryId(queryId);
            if (rank instanceof Number) {
                clickLog.setOrder(((Number) rank).intValue());
            }
            ComponentUtil.getSearchLogHelper().addClickLog(clickLog);
            if (logger.isDebugEnabled()) {
                logger.debug("logged click: docId={}, queryId={}, url={}", docId, queryId, url);
            }
            ComponentUtil.getV2EnvelopeWriter().writeSuccess(res, Map.of("ok", true, "logged", true));
        } catch (final Exception e) {
            ComponentUtil.getV2EnvelopeWriter().writeInternalError(res, e, logger, "/api/v2/click");
        }
    }

public void handle(final HttpServletRequest req, final HttpServletResponse res) throws IOException {
        if (!"POST".equalsIgnoreCase(req.getMethod())) {
            res.setHeader("Allow", "POST");
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.METHOD_NOT_ALLOWED, "method not allowed");
            return;
        }
        final LoginRateLimiter limiter = limiter();
        final FessConfig fessConfig = ComponentUtil.getFessConfig();
        final int ipLimit = fessConfig.getThemeApiLoginRateLimitPerIpPerMinuteAsInteger();
        final int userLimit = fessConfig.getThemeApiLoginRateLimitPerUserPerMinuteAsInteger();
        final int lockoutSec = fessConfig.getThemeApiLoginLockoutSecondsAsInteger();
        final String clientIp = resolveClientIp(req);

        if (!limiter.allow(LoginRateLimiter.Scope.IP, clientIp, ipLimit, 60)) {
            // The rate-limit gates used to be completely silent, so an operator investigating
            // "login stopped working" had nothing in fess.log to go on. ActivityHelper has no
            // activity type for a throttled attempt and inventing one would change the audit
            // schema, so the record goes to the ordinary log instead.
            //
            // Only the request that actually arms the lockout is a new security event. Every
            // later request during the same lockout also reaches this branch, so logging them
            // all at WARN would let a client that keeps retrying pump the log without bound.
            if (limiter.lockOut(LoginRateLimiter.Scope.IP, clientIp, lockoutSec)) {
                logger.warn("[v2/login] ip rate limit exceeded; locking out for {}s: clientIp={}, limit={}/min", lockoutSec, clientIp,
                        ipLimit);
            } else if (logger.isDebugEnabled()) {
                logger.debug("[v2/login] refused a retry during the active ip lockout: clientIp={}", clientIp);
            }
            res.setHeader("Retry-After", Integer.toString(lockoutSec));
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.RATE_LIMITED, "too many login attempts (ip)");
            return;
        }

        final Map<String, Object> body;
        try {
            body = ComponentUtil.getV2JsonBody().read(req, MAX_BODY_BYTES);
        } catch (final V2JsonBody.PayloadTooLargeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "payload too large");
            return;
        } catch (final V2JsonBody.MalformedJsonException | V2JsonBody.UnsupportedMediaTypeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, e.getMessage());
            return;
        }
        final String username = stringOrNull(body.get("username"));
        final String password = stringOrNull(body.get("password"));
        final String returnTo = stringOrNull(body.get("return_to"));
        if (StringUtil.isBlank(username) || StringUtil.isBlank(password)) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "username and password are required");
            return;
        }
        try {
            if (username.length() > 100) {
                throw new InvalidRequestParameterException("username exceeds the maximum length of 100");
            }
            if (password.length() > fessConfig.getPasswordMaxLengthOrDefault()) {
                throw new InvalidRequestParameterException("password exceeds the maximum length");
            }
        } catch (final InvalidRequestParameterException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, e.getMessage());
            return;
        }
        final String userKey = userScopeKey(clientIp, username);

        // USER-scope pre-validation uses peek() so the bucket is NOT consumed yet. The slot is
        // taken only on credential failure below, so a system-error path (e.g. login subsystem
        // down) does not count against the legitimate user's bucket. The USER bucket is keyed by
        // (clientIp, username) so an attacker cannot lock a victim's account from a different IP.
        if (!limiter.peek(LoginRateLimiter.Scope.USER, userKey, userLimit, 60)) {
            // Keep stamping the lockout internally (protects this (IP,user) pair), but do
            // NOT disclose the per-user rate-limit state. Return a generic 401 identical to a
            // credential rejection, with no Retry-After, so the response cannot be used to probe
            // a per-user counter. The IP-scope gate above still returns 429 + Retry-After.
            // The response is deliberately indistinguishable from a credential rejection, so the
            // server log is the only place the throttling is visible. No LOGIN_FAILURE audit
            // record is written here: no credential was actually checked. As with the ip gate,
            // only the request that arms the lockout is logged at WARN — and this gate needs
            // that guard the most, because the client is told nothing about the throttling and
            // therefore has no reason to back off.
            if (limiter.lockOut(LoginRateLimiter.Scope.USER, userKey, lockoutSec)) {
                logger.warn("[v2/login] user rate limit exceeded; locking out for {}s: username={}, clientIp={}, limit={}/min", lockoutSec,
                        username, clientIp, userLimit);
            } else if (logger.isDebugEnabled()) {
                logger.debug("[v2/login] refused a retry during the active user lockout: username={}, clientIp={}", username, clientIp);
            }
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.AUTH_REQUIRED, "invalid credentials");
            return;
        }

        // Acquire the login assist component INSIDE the try so an early DI binding failure
        // (which only happens in slim test harnesses, but defense in depth) is treated as a
        // system error rather than a credential failure — the user bucket must not be
        // consumed for DI breakage.
        final FessLoginAssist assist;
        try {
            assist = ComponentUtil.getFessLoginAssist();
        } catch (final RuntimeException e) {
            logger.warn("login failed unexpectedly: could not acquire FessLoginAssist", e);
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INTERNAL_ERROR, "internal error");
            return;
        }

        // C-2: POST /auth/login MUST always verify the supplied password. We previously had a
        // "same-user fast path" that returned a fresh CSRF token when the existing session was
        // already bound to the same userId — that branch skipped credential verification AND
        // rate-limiting AND session-id rotation, letting any holder of a valid session cookie
        // confirm session validity and rotate CSRF tokens without proving the password. The
        // intended "refresh CSRF token while keeping session" use case belongs to
        // GET /api/v2/ui/config, not the login endpoint. So we always go through assist.login()
        // regardless of existing session state; the post-success changeSessionId() handles
        // session fixation, and an account-switch is just the natural outcome of a fresh login.
        // Capture the previous user ID BEFORE authentication so it is available for the
        // post-success audit log, without logging anything here (A-1: avoid false-positive
        // audit lines when credentials are subsequently rejected).
        final String prevUserId;
        try {
            final OptionalThing<FessUserBean> existingBean = assist.getSavedUserBean();
            prevUserId = existingBean.isPresent() ? existingBean.get().getUserId() : null;
        } catch (final RuntimeException e) {
            logger.warn("login: could not check existing session state", e);
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INTERNAL_ERROR, "internal error");
            return;
        }

        try {
            assist.login(new LocalUserCredential(username, password), op -> {});
        } catch (final LoginFailureException e) {
            // Mirror LoginAction.login(): log the rejection and write the LOGIN_FAILURE record to
            // audit.log. Without this the v2 endpoint left no trace of failed authentication at
            // all, so brute-force attempts against the SPA login form were undetectable.
            if (logger.isInfoEnabled()) {
                logger.info("[v2/login] login failed: username={}, reason={}", username, e.getMessage());
            }
            recordLoginFailureActivity(username, password);
            // Credential rejection consumes the USER slot exactly once, on the failure path
            // (keyed by (clientIp, username)). When the window is exhausted we also stamp a
            // lockUntil so subsequent requests from this (IP,user) are refused even after the
            // sliding window expires. The response is a generic 401 in BOTH cases (exhausted
            // or not), with no Retry-After, so the per-user counter state never leaks.
            if (!limiter.allow(LoginRateLimiter.Scope.USER, userKey, userLimit, 60)) {
                if (limiter.lockOut(LoginRateLimiter.Scope.USER, userKey, lockoutSec)) {
                    logger.warn("[v2/login] user rate limit exhausted; locking out for {}s: username={}, clientIp={}, limit={}/min",
                            lockoutSec, username, clientIp, userLimit);
                } else if (logger.isDebugEnabled()) {
                    // The peek() gate above admitted this request, so an active lockout here
                    // means a concurrent request armed it in between — already reported.
                    logger.debug("[v2/login] user bucket exhausted while a lockout was already active: username={}, clientIp={}", username,
                            clientIp);
                }
            }
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.AUTH_REQUIRED, "invalid credentials");
            return;
        } catch (final RuntimeException e) {
            // Anything else (DI binding failure, transient lookup error, etc.) is a system
            // error and must NOT count against the user bucket — otherwise a misconfigured
            // server would lock real users out. We surface INTERNAL_ERROR with a generic
            // message; the exception detail goes to the log only.
            logger.warn("login failed unexpectedly", e);
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INTERNAL_ERROR, "internal error");
            return;
        }

        // Mirror LoginAction.login(): write the LOGIN record to audit.log as soon as the
        // credentials are verified — before the session/CSRF work below — so the record survives
        // a later failure in that machinery.
        recordLoginActivity(assist);

        // A-1: emit account-switch audit log AFTER successful credential verification so
        // that an unauthenticated attacker with a stolen session cookie cannot trigger a
        // false-positive audit line by posting bad credentials for a different username.
        if (prevUserId != null && !username.equals(prevUserId)) {
            logger.info("[v2/login] account switch: prevUserId={}, newUserId={}", prevUserId, username);
        }

        // Successful login — rotate the session id to defeat session fixation, then issue
        // a fresh CSRF token. changeSessionId() throws IllegalStateException if no session
        // exists yet; for the v2 API path that can happen when the SPA POSTs without first
        // making a GET — the catch swallows it because the subsequent getSession(true) will
        // create a fresh session anyway.
        try {
            req.changeSessionId();
        } catch (final IllegalStateException ignore) {
            // no session was associated with the request yet — getSession(true) below
            // will create a new one, which is itself unfixable from the outside.
        }
        final HttpSession session = req.getSession(true);
        final SessionCsrfTokenManager csrf = ComponentUtil.getComponent(SessionCsrfTokenManager.class);
        csrf.rotate(session);
        final String token = csrf.issue(session);

        // MJ-5: clear both USER and IP rate-limit buckets on successful login so that a
        // legitimate user who exhausted the window (e.g. typo run) is not penalized on
        // their next attempt after providing the correct credentials. The USER bucket is the
        // (clientIp, username) composite.
        limiter.clear(LoginRateLimiter.Scope.USER, userKey);
        limiter.clear(LoginRateLimiter.Scope.IP, clientIp);

        final OptionalThing<FessUserBean> userBean = assist.getSavedUserBean();
        final Map<String, Object> payload;
        if (userBean.isPresent()) {
            payload = buildUserPayload(userBean.get(), token, returnTo);
        } else {
            payload = new LinkedHashMap<>();
            payload.put("csrf_token", token);
            addReturnTo(payload, returnTo);
        }
        ComponentUtil.getV2EnvelopeWriter().writeSuccess(res, payload);
    }

