public void handle(final HttpServletRequest req, final HttpServletResponse res, final String docId) throws IOException {
        if (!"POST".equalsIgnoreCase(req.getMethod())) {
            res.setHeader("Allow", "POST");
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.METHOD_NOT_ALLOWED, "method not allowed");
            return;
        }
        if (!ComponentUtil.getV2DocIdValidator().isValid(docId)) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "invalid doc_id");
            return;
        }
        // Auth check before body parsing — avoids spending CPU on the body for
        // unauthenticated requests and gives the caller a more accurate error.
        //
        // M-17: split DI-binding failure from "no user bean present". Genuine anonymous
        // callers still see AUTH_REQUIRED (401); a system-level lookup failure surfaces
        // as INTERNAL_ERROR (500) so we do not mislead a logged-in user into thinking
        // their session expired when DI is broken.
        final FessLoginAssist assist;
        try {
            assist = ComponentUtil.getFessLoginAssist();
        } catch (final RuntimeException e) {
            logger.warn("/api/v2/documents/{}/favorite POST: could not acquire FessLoginAssist", docId, e);
            ComponentUtil.getV2EnvelopeWriter().writeInternalError(res, e, logger, "/api/v2/documents/" + docId + "/favorite POST");
            return;
        }
        final OptionalThing<FessUserBean> userBean;
        try {
            userBean = assist.getSavedUserBean();
        } catch (final RuntimeException e) {
            logger.warn("/api/v2/documents/{}/favorite POST: getSavedUserBean failed", docId, e);
            ComponentUtil.getV2EnvelopeWriter().writeInternalError(res, e, logger, "/api/v2/documents/" + docId + "/favorite POST");
            return;
        }
        if (!userBean.isPresent()) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.AUTH_REQUIRED, "login required");
            return;
        }
        final FessConfig cfg = ComponentUtil.getFessConfig();
        if (!cfg.isUserFavorite()) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "favorite feature is not available");
            return;
        }
        final UserInfoHelper userInfoHelper = ComponentUtil.getUserInfoHelper();
        final String userCode = userInfoHelper.getUserCode();
        if (StringUtil.isBlank(userCode)) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.AUTH_REQUIRED, "no user session");
            return;
        }
        final Map<String, Object> body;
        try {
            body = ComponentUtil.getV2JsonBody().read(req, MAX_BODY_BYTES);
        } catch (final V2JsonBody.PayloadTooLargeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.PAYLOAD_TOO_LARGE, e.getMessage());
            return;
        } catch (final V2JsonBody.UnsupportedMediaTypeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.UNSUPPORTED_MEDIA_TYPE, e.getMessage());
            return;
        } catch (final V2JsonBody.MalformedJsonException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, e.getMessage());
            return;
        }
        final String queryId = (String) body.get("query_id");
        if (StringUtil.isBlank(queryId)) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "query_id is required");
            return;
        }
        if (queryId.length() > QUERY_ID_MAX_LENGTH) {
            ComponentUtil.getV2EnvelopeWriter()
                    .writeError(res, V2ErrorCode.INVALID_REQUEST, "query_id exceeds the maximum length of " + QUERY_ID_MAX_LENGTH);
            return;
        }
        if (!QUERY_ID_PATTERN.matcher(queryId).matches()) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "query_id contains invalid characters");
            return;
        }

        // MJ-23: query_id arrives in a JSON body — it is already plain text (not
        // URL-encoded). Passing it through URLDecoder.decode would silently mangle
        // values that legitimately contain '+' or '%xx' characters. The wire contract
        // is that query_id is whatever the /search endpoint returned in its query_id
        // field, treated as opaque. Pass it directly to getResultDocIds.
        final String[] docIds;
        try {
            docIds = userInfoHelper.getResultDocIds(queryId);
        } catch (final Exception e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "invalid query_id");
            return;
        }
        if (docIds == null) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "no searched urls");
            return;
        }
        if (!ArrayUtils.contains(docIds, docId)) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.NOT_FOUND, "doc not in search result");
            return;
        }

        final SearchHelper searchHelper = ComponentUtil.getSearchHelper();
        final SystemHelper systemHelper = ComponentUtil.getSystemHelper();
        final FavoriteLogService favoriteLogService = ComponentUtil.getComponent(FavoriteLogService.class);

        // Holds the favorite count read from the document inside the lambda so
        // the outer scope can include it in the success envelope.
        final long[] favoriteCountHolder = { 0L };

        try {
            searchHelper
                    .getDocumentByDocId(docId,
                            new String[] { cfg.getIndexFieldUrl(), cfg.getIndexFieldLang(), cfg.getIndexFieldFavoriteCount() },
                            OptionalThing.empty())
                    .ifPresent(doc -> {
                        final String favoriteUrl = DocumentUtil.getValue(doc, cfg.getIndexFieldUrl(), String.class);
                        if (StringUtil.isBlank(favoriteUrl)) {
                            throw new FavoriteAddFailedException("URL is null");
                        }
                        final Long existingCount = DocumentUtil.getValue(doc, cfg.getIndexFieldFavoriteCount(), Long.class);
                        favoriteCountHolder[0] = existingCount == null ? 0L : existingCount;

                        // M-9: re-POSTing the same favorite is an idempotent no-op success, not
                        // a 500. The duplicate is signalled via a marker exception so the outer
                        // catch can short-circuit the favorite-count bump and emit a 200 success
                        // envelope. A user code that resolves to no user is a different outcome:
                        // nothing was written, so it must not be reported as already favorited.
                        final FavoriteResult result = favoriteLogService.addUrl(userCode, (userInfo, favoriteLog) -> {
                            favoriteLog.setUserInfoId(userInfo.getId());
                            favoriteLog.setUrl(favoriteUrl);
                            favoriteLog.setDocId(docId);
                            favoriteLog.setQueryId(queryId);
                            favoriteLog.setCreatedAt(systemHelper.getCurrentTimeAsLocalDateTime());
                        });
                        if (result == FavoriteResult.ALREADY_ADDED) {
                            throw new AlreadyFavoritedException();
                        }
                        if (result == FavoriteResult.NO_SUCH_USER) {
                            throw new FavoriteAddFailedException("no user for the given user code");
                        }
                        // Optimistically bump the count for the fresh-add case.
                        favoriteCountHolder[0] = favoriteCountHolder[0] + 1L;
                        final String id = DocumentUtil.getValue(doc, cfg.getIndexFieldId(), String.class);
                        searchHelper.update(id, builder -> {
                            final Script script = ComponentUtil.getLanguageHelper()
                                    .createScript(doc, "ctx._source." + cfg.getIndexFieldFavoriteCount() + "+=1");
                            builder.setScript(script);
                            final Map<String, Object> upsertMap = new HashMap<>();
                            upsertMap.put(cfg.getIndexFieldFavoriteCount(), 1);
                            builder.setUpsert(upsertMap);
                            builder.setRefreshPolicy(Constants.TRUE);
                        });
                    })
                    .orElse(() -> {
                        throw new DocNotFoundException("doc not found: " + docId);
                    });
        } catch (final DocNotFoundException e) {
            logger.warn("/api/v2/documents/{}/favorite POST: doc not found", docId, e);
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.NOT_FOUND, "doc not found: " + docId);
            return;
        } catch (final AlreadyFavoritedException e) {
            // M-9: idempotent re-POST — return 200 with the full payload shape so the
            // SPA receives favorite:true and the current count regardless of whether
            // this was a fresh add or a duplicate.
            if (logger.isDebugEnabled()) {
                logger.debug("/api/v2/documents/{}/favorite POST: already favorited (idempotent no-op)", docId);
            }
            final Map<String, Object> idempotentPayload = new java.util.LinkedHashMap<>();
            idempotentPayload.put("doc_id", docId);
            idempotentPayload.put("ok", true);
            idempotentPayload.put("favorite", true);
            idempotentPayload.put("count", favoriteCountHolder[0]);
            idempotentPayload.put("already_existed", true);
            ComponentUtil.getV2EnvelopeWriter().writeSuccess(res, idempotentPayload);
            return;
        } catch (final FavoriteAddFailedException e) {
            logger.warn("/api/v2/documents/{}/favorite POST: add failed", docId, e);
            ComponentUtil.getV2EnvelopeWriter().writeInternalError(res, e, logger, "/api/v2/documents/" + docId + "/favorite POST");
            return;
        } catch (final RuntimeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeInternalError(res, e, logger, "/api/v2/documents/" + docId + "/favorite POST");
            return;
        }

        final Map<String, Object> successPayload = new java.util.LinkedHashMap<>();
        successPayload.put("doc_id", docId);
        successPayload.put("ok", true);
        successPayload.put("favorite", true);
        successPayload.put("count", favoriteCountHolder[0]);
        ComponentUtil.getV2EnvelopeWriter().writeSuccess(res, successPayload);
    }

protected void executeThumbnailGenerator() {
        final List<String> cmdList = new ArrayList<>();
        final String cpSeparator = SystemUtils.IS_OS_WINDOWS ? ";" : ":";
        final ServletContext servletContext = ComponentUtil.getComponent(ServletContext.class);
        final ProcessHelper processHelper = ComponentUtil.getProcessHelper();
        final FessConfig fessConfig = ComponentUtil.getFessConfig();

        cmdList.add(fessConfig.getJavaCommandPath());

        // -cp
        cmdList.add("-cp");
        final StringBuilder buf = new StringBuilder(100);
        ResourceUtil.getOverrideConfPath().ifPresent(p -> {
            buf.append(p);
            buf.append(cpSeparator);
        });
        final String confPath = System.getProperty(Constants.FESS_CONF_PATH);
        if (StringUtil.isNotBlank(confPath)) {
            buf.append(confPath);
            buf.append(cpSeparator);
        }
        // WEB-INF/env/thumbnail/resources
        buf.append("WEB-INF");
        buf.append(File.separator);
        buf.append("env");
        buf.append(File.separator);
        buf.append(getExecuteType());
        buf.append(File.separator);
        buf.append("resources");
        buf.append(cpSeparator);
        // WEB-INF/classes
        buf.append("WEB-INF");
        buf.append(File.separator);
        buf.append("classes");
        // target/classes
        final String userDir = System.getProperty("user.dir");
        final File targetDir = new File(userDir, "target");
        final File targetClassesDir = new File(targetDir, "classes");
        if (targetClassesDir.isDirectory()) {
            buf.append(cpSeparator);
            buf.append(targetClassesDir.getAbsolutePath());
        }
        // WEB-INF/lib
        appendJarFile(cpSeparator, buf, new File(servletContext.getRealPath("/WEB-INF/lib")),
                "WEB-INF" + File.separator + "lib" + File.separator);
        // WEB-INF/env/thumbnail/lib
        appendJarFile(cpSeparator, buf, new File(servletContext.getRealPath("/WEB-INF/env/" + getExecuteType() + "/lib")),
                "WEB-INF" + File.separator + "env" + File.separator + getExecuteType() + File.separator + "lib" + File.separator);
        // WEB-INF/plugin
        appendJarFile(cpSeparator, buf, new File(servletContext.getRealPath("/WEB-INF/plugin")),
                "WEB-INF" + File.separator + "plugin" + File.separator);
        final File targetLibDir = new File(targetDir, "fess" + File.separator + "WEB-INF" + File.separator + "lib");
        if (targetLibDir.isDirectory()) {
            appendJarFile(cpSeparator, buf, targetLibDir, targetLibDir.getAbsolutePath() + File.separator);
        }
        cmdList.add(buf.toString());

        if (useLocalFesen) {
            final String httpAddress = SystemUtil.getSearchEngineHttpAddress();
            if (StringUtil.isNotBlank(httpAddress)) {
                cmdList.add("-D" + Constants.FESS_SEARCH_ENGINE_HTTP_ADDRESS + "=" + httpAddress);
            }
        }

        final String systemLastaEnv = System.getProperty("lasta.env");
        if (StringUtil.isNotBlank(systemLastaEnv)) {
            if ("web".equals(systemLastaEnv)) {
                cmdList.add("-Dlasta.env=" + getExecuteType());
            } else {
                cmdList.add("-Dlasta.env=" + systemLastaEnv);
            }
        } else if (StringUtil.isNotBlank(lastaEnv)) {
            cmdList.add("-Dlasta.env=" + lastaEnv);
        } else {
            cmdList.add("-Dlasta.env=" + getExecuteType());
        }

        addFessConfigProperties(cmdList);
        addFessSystemProperties(cmdList);
        addFessCustomSystemProperties(cmdList, fessConfig.getJobSystemPropertyFilterPattern());
        addSystemProperty(cmdList, Constants.FESS_CONF_PATH, null, null);
        addSystemProperty(cmdList, Constants.FESS_HOME, null, null);
        cmdList.add("-Dfess." + getExecuteType() + ".process=true");
        if (logFilePath == null) {
            final String value = System.getProperty("fess.log.path");
            logFilePath = value != null ? value : new File(targetDir, "logs").getAbsolutePath();
        }
        cmdList.add("-Dfess.log.path=" + logFilePath);
        addSystemProperty(cmdList, Constants.FESS_VAR_PATH, null, null);
        addSystemProperty(cmdList, Constants.FESS_THUMBNAIL_PATH, null, null);
        addSystemProperty(cmdList, "fess.log.name", getLogName("fess"), getLogName(StringUtil.EMPTY));
        if (logLevel != null) {
            cmdList.add("-Dfess.log.level=" + logLevel);
        }
        stream(fessConfig.getJvmThumbnailOptionsAsArray())
                .of(stream -> stream.filter(StringUtil::isNotBlank).forEach(value -> cmdList.add(value)));

        File ownTmpDir = null;
        final String tmpDir = System.getProperty("java.io.tmpdir");
        if (fessConfig.isUseOwnTmpDir() && StringUtil.isNotBlank(tmpDir)) {
            ownTmpDir = new File(tmpDir, "fessTmpDir_" + sessionId);
            if (ownTmpDir.mkdirs()) {
                cmdList.add("-Djava.io.tmpdir=" + ownTmpDir.getAbsolutePath());
            } else {
                ownTmpDir = null;
            }
        }

        if (!jvmOptions.isEmpty()) {
            jvmOptions.stream().filter(StringUtil::isNotBlank).forEach(cmdList::add);
        }

        cmdList.add(ThumbnailGenerator.class.getCanonicalName());

        cmdList.add("--sessionId");
        cmdList.add(sessionId);
        cmdList.add("--numOfThreads");
        cmdList.add(Integer.toString(numOfThreads));
        if (cleanup) {
            cmdList.add("--cleanup");
        }

        final File propFile = ComponentUtil.getSystemHelper().createTempFile(getExecuteType() + "_", ".properties");
        try {
            cmdList.add("-p");
            cmdList.add(propFile.getAbsolutePath());
            createSystemProperties(cmdList, propFile);

            final File baseDir = new File(servletContext.getRealPath("/WEB-INF")).getParentFile();

            if (logger.isInfoEnabled()) {
                logger.info("ThumbnailGenerator: \nDirectory={}\nOptions={}", baseDir, cmdList);
            }

            final JobProcess jobProcess = processHelper.startProcess(sessionId, cmdList, pb -> {
                pb.directory(baseDir);
                pb.redirectErrorStream(true);
            });

            final InputStreamThread it = jobProcess.getInputStreamThread();
            it.start();

            final Process currentProcess = jobProcess.getProcess();
            currentProcess.waitFor();
            it.join(5000);

            final int exitValue = currentProcess.exitValue();

            if (logger.isInfoEnabled()) {
                logger.info("ThumbnailGenerator: Exit Code={} - Process Output:\n{}", exitValue, it.getOutput());
            }
            if (exitValue != 0) {
                final StringBuilder out = new StringBuilder();
                if (processTimeout) {
                    out.append("Process is terminated due to ").append(timeout).append(" second exceeded.\n");
                }
                out.append("Exit Code: ").append(exitValue).append("\nOutput:\n").append(it.getOutput());
                throw new JobProcessingException(out.toString());
            }
            ComponentUtil.getPopularWordHelper().clearCache();
        } catch (final JobProcessingException e) {
            throw e;
        } catch (final Exception e) {
            throw new JobProcessingException("ThumbnailGenerator Process terminated.", e);
        } finally {
            try {
                processHelper.destroyProcess(sessionId);
            } finally {
                if (propFile != null && !propFile.delete()) {
                    logger.warn("Failed to delete properties file: {}", propFile.getAbsolutePath());
                }
                deleteTempDir(ownTmpDir);
            }
        }
    }

public boolean reindexConfigIndices(final boolean loadBulkData, final Set<String> targetPrefixes) {
        final FessConfig fessConfig = ComponentUtil.getFessConfig();
        final String timestamp = new SimpleDateFormat(Constants.DOCUMENT_INDEX_SUFFIX_PATTERN).format(new Date());
        boolean success = true;

        for (final String configName : indexConfigList) {
            final String[] values = configName.split("/");
            if (values.length != 2) {
                continue;
            }

            final String configIndex = values[0];
            final String configType = values[1];

            if (DOC_INDEX.equals(configIndex)) {
                continue;
            }

            final String indexName;
            if (configIndex.startsWith(CONFIG_INDEX_PREFIX)) {
                if (!targetPrefixes.contains(CONFIG_INDEX_PREFIX)) {
                    continue;
                }
                indexName = configIndex.replaceFirst(Pattern.quote(CONFIG_INDEX_PREFIX), fessConfig.getIndexConfigIndex());
            } else if (configIndex.startsWith(USER_INDEX_PREFIX)) {
                if (!targetPrefixes.contains(USER_INDEX_PREFIX)) {
                    continue;
                }
                indexName = configIndex.replaceFirst(Pattern.quote(USER_INDEX_PREFIX), fessConfig.getIndexUserIndex());
            } else if (configIndex.startsWith(LOG_INDEX_PREFIX)) {
                if (!targetPrefixes.contains(LOG_INDEX_PREFIX)) {
                    continue;
                }
                indexName = configIndex.replaceFirst(Pattern.quote(LOG_INDEX_PREFIX), fessConfig.getIndexLogIndex());
            } else {
                logger.warn("[Rebuild] Unknown config index: {}", configIndex);
                success = false;
                continue;
            }

            if (!existsIndex(indexName)) {
                logger.info("[Rebuild] Creating new index: {}", indexName);
                if (!createIndex(configIndex, indexName)) {
                    logger.warn("[Rebuild] Failed to create index: {}", indexName);
                    success = false;
                    continue;
                }
                try {
                    addMapping(configIndex, configType, indexName, loadBulkData);
                    createAlias(configIndex, indexName);
                } catch (final Exception e) {
                    logger.warn("[Rebuild] Failed to set up index: {}", indexName, e);
                    success = false;
                }
                continue;
            }

            final String backupIndex = indexName + ".backup." + timestamp;
            logger.info("[Rebuild] Starting rebuild for {}", indexName);

            try {
                final long sourceCount = getDocumentCount(indexName);

                // 1. Create backup index with new mappings
                if (!createIndex(configIndex, backupIndex)) {
                    logger.warn("[Rebuild] Failed to create backup index: {}", backupIndex);
                    success = false;
                    continue;
                }
                addMapping(configIndex, configType, backupIndex, false);

                // 2. Reindex current -> backup and verify document count
                if (!reindex(indexName, backupIndex, true)) {
                    logger.warn("[Rebuild] Failed to reindex from {} to {}", indexName, backupIndex);
                    deleteIndex(backupIndex);
                    success = false;
                    continue;
                }
                if (sourceCount >= 0) {
                    final long backupCount = getDocumentCount(backupIndex);
                    if (backupCount != sourceCount) {
                        logger.warn("[Rebuild] Document count mismatch after reindex: source={}, backup={} for {}", sourceCount,
                                backupCount, indexName);
                        deleteIndex(backupIndex);
                        success = false;
                        continue;
                    }
                }

                // 3. Delete old index and recreate with the same name (Bhv layer caches concrete index names)
                deleteIndex(indexName);
                if (!createIndex(configIndex, indexName)) {
                    logger.warn("[Rebuild] Failed to recreate index: {}. Keeping backup: {}", indexName, backupIndex);
                    success = false;
                    continue;
                }
                addMapping(configIndex, configType, indexName, false);

                // 4. Reindex backup -> recreated index and verify document count
                if (!reindex(backupIndex, indexName, true)) {
                    logger.warn("[Rebuild] Failed to reindex from {} to {}. Cleaning up.", backupIndex, indexName);
                    deleteIndex(backupIndex);
                    success = false;
                    continue;
                }
                if (sourceCount >= 0) {
                    final long rebuiltCount = getDocumentCount(indexName);
                    if (rebuiltCount != sourceCount) {
                        logger.warn("[Rebuild] Document count mismatch after rebuild: expected={}, actual={} for {}", sourceCount,
                                rebuiltCount, indexName);
                        deleteIndex(backupIndex);
                        success = false;
                        continue;
                    }
                }

                // 5. Optionally load bulk data with CREATE mode
                if (loadBulkData) {
                    final String dataPath =
                            getResourcePath(indexConfigPath, fessConfig.getFesenType(), "/" + configIndex + "/" + configType + ".bulk");
                    if (ResourceUtil.isExist(dataPath)) {
                        insertBulkData(fessConfig, indexName, dataPath, true);
                    }
                    split(fessConfig.getAppExtensionNames(), ",").of(stream -> stream.filter(StringUtil::isNotBlank).forEach(name -> {
                        final String bulkPath = getResourcePath(indexConfigPath, fessConfig.getFesenType(),
                                "/" + configIndex + "/" + configType + "_" + name + ".bulk");
                        if (ResourceUtil.isExist(bulkPath)) {
                            insertBulkData(fessConfig, indexName, bulkPath, true);
                        }
                    }));
                }

                // 6. Recreate aliases on the rebuilt index
                createAlias(configIndex, indexName);

                // 7. Delete backup
                deleteIndex(backupIndex);

                logger.info("[Rebuild] Completed rebuild for {}", indexName);
            } catch (final Exception e) {
                logger.warn("[Rebuild] Failed to rebuild index: {}", indexName, e);
                if (existsIndex(backupIndex)) {
                    logger.info("[Rebuild] Backup index {} remains for recovery", backupIndex);
                }
                success = false;
            }
        }
        return success;
    }

protected void executeChunkVectorIndexer() {
        final List<String> cmdList = new ArrayList<>();
        final String cpSeparator = SystemUtils.IS_OS_WINDOWS ? ";" : ":";
        final ServletContext servletContext = getServletContext();
        final ProcessHelper processHelper = ComponentUtil.getProcessHelper();
        final FessConfig fessConfig = ComponentUtil.getFessConfig();

        cmdList.add(fessConfig.getJavaCommandPath());

        // -cp
        cmdList.add("-cp");
        final StringBuilder buf = new StringBuilder(100);
        ResourceUtil.getOverrideConfPath().ifPresent(p -> {
            buf.append(p);
            buf.append(cpSeparator);
        });
        final String confPath = System.getProperty(Constants.FESS_CONF_PATH);
        if (StringUtil.isNotBlank(confPath)) {
            buf.append(confPath);
            buf.append(cpSeparator);
        }
        // WEB-INF/env/chunk/resources
        buf.append("WEB-INF");
        buf.append(File.separator);
        buf.append("env");
        buf.append(File.separator);
        buf.append(getExecuteType());
        buf.append(File.separator);
        buf.append("resources");
        buf.append(cpSeparator);
        // WEB-INF/classes
        buf.append("WEB-INF");
        buf.append(File.separator);
        buf.append("classes");
        // target/classes
        final String userDir = System.getProperty("user.dir");
        final File targetDir = new File(userDir, "target");
        final File targetClassesDir = new File(targetDir, "classes");
        if (targetClassesDir.isDirectory()) {
            buf.append(cpSeparator);
            buf.append(targetClassesDir.getAbsolutePath());
        }
        // WEB-INF/lib
        appendJarFile(cpSeparator, buf, new File(servletContext.getRealPath("/WEB-INF/lib")),
                "WEB-INF" + File.separator + "lib" + File.separator);
        // WEB-INF/env/chunk/lib
        appendJarFile(cpSeparator, buf, new File(servletContext.getRealPath("/WEB-INF/env/" + getExecuteType() + "/lib")),
                "WEB-INF" + File.separator + "env" + File.separator + getExecuteType() + File.separator + "lib" + File.separator);
        // WEB-INF/plugin
        appendJarFile(cpSeparator, buf, new File(servletContext.getRealPath("/WEB-INF/plugin")),
                "WEB-INF" + File.separator + "plugin" + File.separator);
        final File targetLibDir = new File(targetDir, "fess" + File.separator + "WEB-INF" + File.separator + "lib");
        if (targetLibDir.isDirectory()) {
            appendJarFile(cpSeparator, buf, targetLibDir, targetLibDir.getAbsolutePath() + File.separator);
        }
        cmdList.add(buf.toString());

        if (useLocalFesen) {
            final String httpAddress = SystemUtil.getSearchEngineHttpAddress();
            if (StringUtil.isNotBlank(httpAddress)) {
                cmdList.add("-D" + Constants.FESS_SEARCH_ENGINE_HTTP_ADDRESS + "=" + httpAddress);
            }
        }

        final String systemLastaEnv = System.getProperty("lasta.env");
        if (StringUtil.isNotBlank(systemLastaEnv)) {
            if ("web".equals(systemLastaEnv)) {
                cmdList.add("-Dlasta.env=" + getExecuteType());
            } else {
                cmdList.add("-Dlasta.env=" + systemLastaEnv);
            }
        } else if (StringUtil.isNotBlank(lastaEnv)) {
            cmdList.add("-Dlasta.env=" + lastaEnv);
        } else {
            cmdList.add("-Dlasta.env=" + getExecuteType());
        }

        addFessConfigProperties(cmdList);
        addFessSystemProperties(cmdList);
        addFessCustomSystemProperties(cmdList, fessConfig.getJobSystemPropertyFilterPattern());
        addSystemProperty(cmdList, Constants.FESS_CONF_PATH, null, null);
        cmdList.add("-Dfess." + getExecuteType() + ".process=true");
        if (logFilePath == null) {
            final String value = System.getProperty("fess.log.path");
            logFilePath = value != null ? value : new File(targetDir, "logs").getAbsolutePath();
        }
        cmdList.add("-Dfess.log.path=" + logFilePath);
        addSystemProperty(cmdList, "fess.log.name", getLogName("fess"), getLogName(StringUtil.EMPTY));
        if (logLevel == null) {
            addSystemProperty(cmdList, "fess.log.level", null, null);
        } else {
            cmdList.add("-Dfess.log.level=" + logLevel);
        }
        stream(fessConfig.getJvmChunkOptionsAsArray())
                .of(stream -> stream.filter(StringUtil::isNotBlank).forEach(value -> cmdList.add(value)));

        File ownTmpDir = null;
        final String tmpDir = System.getProperty("java.io.tmpdir");
        if (fessConfig.isUseOwnTmpDir() && StringUtil.isNotBlank(tmpDir)) {
            ownTmpDir = new File(tmpDir, "fessTmpDir_" + sessionId);
            if (ownTmpDir.mkdirs()) {
                cmdList.add("-Djava.io.tmpdir=" + ownTmpDir.getAbsolutePath());
            } else {
                ownTmpDir = null;
            }
        }

        if (!jvmOptions.isEmpty()) {
            jvmOptions.stream().filter(StringUtil::isNotBlank).forEach(cmdList::add);
        }

        cmdList.add(ChunkVectorIndexer.class.getCanonicalName());

        cmdList.add("--sessionId");
        cmdList.add(sessionId);

        final File propFile = ComponentUtil.getSystemHelper().createTempFile(getExecuteType() + "_", ".properties");
        try {
            cmdList.add("-p");
            cmdList.add(propFile.getAbsolutePath());
            createSystemProperties(cmdList, propFile);

            final File baseDir = new File(servletContext.getRealPath("/WEB-INF")).getParentFile();

            if (logger.isInfoEnabled()) {
                logger.info("ChunkVectorIndexer: \nDirectory={}\nOptions={}", baseDir, cmdList);
            }

            final JobProcess jobProcess = processHelper.startProcess(sessionId, cmdList, pb -> {
                pb.directory(baseDir);
                pb.redirectErrorStream(true);
            });

            final InputStreamThread it = jobProcess.getInputStreamThread();
            it.start();

            final Process currentProcess = jobProcess.getProcess();
            currentProcess.waitFor();
            it.join(5000);

            final int exitValue = currentProcess.exitValue();

            if (logger.isInfoEnabled()) {
                logger.info("ChunkVectorIndexer: Exit Code={} - Process Output:\n{}", exitValue, it.getOutput());
            }
            if (exitValue != 0) {
                final StringBuilder out = new StringBuilder();
                if (processTimeout) {
                    out.append("Process is terminated due to ").append(timeout).append(" second exceeded.\n");
                }
                out.append("Exit Code: ").append(exitValue).append("\nOutput:\n").append(it.getOutput());
                throw new JobProcessingException(out.toString());
            }
        } catch (final JobProcessingException e) {
            throw e;
        } catch (final Exception e) {
            throw new JobProcessingException("ChunkVectorIndexer Process terminated.", e);
        } finally {
            try {
                processHelper.destroyProcess(sessionId);
            } finally {
                if (propFile != null && !propFile.delete()) {
                    logger.warn("Failed to delete properties file: {}", propFile.getAbsolutePath());
                }
                deleteTempDir(ownTmpDir);
            }
        }
    }

public void handle(final HttpServletRequest req, final HttpServletResponse res) throws IOException {
        // --- Gate checks: ALL validation runs before any SSE headers are set. ---
        // Pre-stream failures return proper HTTP status via ComponentUtil.getV2EnvelopeWriter().writeError
        // (application/json). SSE headers are only committed after every gate passes.

        if (!"POST".equalsIgnoreCase(req.getMethod())) {
            res.setHeader("Allow", "POST");
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.METHOD_NOT_ALLOWED, "method not allowed");
            return;
        }

        final FessConfig fessConfig = ComponentUtil.getFessConfig();
        if (!fessConfig.isRagChatEnabled()) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "chat is not enabled");
            return;
        }

        final Map<String, Object> raw;
        try {
            raw = ComponentUtil.getV2JsonBody().read(req, MAX_BODY_BYTES);
        } catch (final V2JsonBody.PayloadTooLargeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.PAYLOAD_TOO_LARGE, e.getMessage());
            return;
        } catch (final V2JsonBody.UnsupportedMediaTypeException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.UNSUPPORTED_MEDIA_TYPE, e.getMessage());
            return;
        } catch (final V2JsonBody.MalformedJsonException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, e.getMessage());
            return;
        }

        final int maxLen = ComponentUtil.getChatApiHelper().getMaxMessageLength(fessConfig);
        final ChatRequestBody body;
        try {
            body = ComponentUtil.getChatApiHelper().parseRequestBody(raw, maxLen);
        } catch (final ChatRequestBody.InvalidRequestException e) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, e.getMessage());
            return;
        }

        if (StringUtil.isBlank(body.message())) {
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INVALID_REQUEST, "message is required");
            return;
        }

        final String userId = getUserId(req);
        // Per-user chat rate limit. Pre-stream failure returns a proper 429 JSON envelope.
        final LoginRateLimiter limiter;
        try {
            limiter = ComponentUtil.getLoginRateLimiter();
        } catch (final RuntimeException e) {
            // Limiter DI not available (e.g. slim test harness); log and surface as 500.
            logger.warn("[RAG] /api/v2/chat/stream rate-limit lookup failed", e);
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.INTERNAL_ERROR, "internal error");
            return;
        }
        final int chatLimit = fessConfig.getChatRateLimitPerMinute();
        // Throttle by a key an anonymous caller cannot rotate (see ChatApiHelper#resolveChatRateLimitKey);
        // the key is always non-blank so the throttle always applies. userId above stays for chat-session binding.
        final String rateLimitKey = getRateLimitKey(req);
        if (limiter != null && chatLimit > 0 && StringUtil.isNotBlank(rateLimitKey)
                && !limiter.allow(LoginRateLimiter.Scope.CHAT, rateLimitKey, chatLimit, 60)) {
            res.setHeader("Retry-After", "60");
            ComponentUtil.getV2EnvelopeWriter().writeError(res, V2ErrorCode.RATE_LIMITED, "too many chat requests");
            return;
        }

        // --- All gates passed: now commit to SSE framing. ---
        // Acquire the writer exactly once. The servlet container manages its lifecycle for
        // the duration of the request; using try-with-resources here would prematurely close
        // the writer and prevent the outer error path from emitting a final SSE event.
        setSseHeaders(res);
        final PrintWriter writer = res.getWriter();
        // Tracks whether the inner phase callback has already emitted an "error" SSE event.
        // The outer catch consults it to avoid emitting a duplicate error event.
        final boolean[] errorEmittedHolder = { false };
        // Shared monitor that serializes ALL writes to the response writer — phase events,
        // chunks, keep-alive pings and the final done/error. Without this, the scheduler
        // thread could interleave a ":keepalive" comment in the middle of an event:/data:
        // pair from the request thread, corrupting the SSE wire format.
        final Object writeLock = new Object();

        // Tag the request for the search-log access-type column, same as v1.
        req.setAttribute(Constants.SEARCH_LOG_ACCESS_TYPE, fessConfig.getSystemProperty("rag.llm.name", "ollama"));

        // Schedule periodic keep-alive pings to defeat idle-connection timeouts on
        // intermediaries (nginx default proxy_read_timeout = 60s) during long LLM phases.
        // The future is cancelled in finally — the shared pool itself is NOT shut down here.
        final long keepaliveMs = resolveKeepaliveIntervalMs(fessConfig);
        final ScheduledFuture<?> pingerFuture = startKeepalivePinger(writer, writeLock, keepaliveMs);

        try {
            final ChatPhaseCallback phaseCallback = newPhaseCallback(writer, errorEmittedHolder, writeLock);

            final ChatResult result;
            if (body.fields().isEmpty() && body.extraQueries().length == 0) {
                result = ComponentUtil.getChatClient().streamChatEnhanced(body.sessionId(), body.message(), userId, phaseCallback);
            } else {
                result = ComponentUtil.getChatClient()
                        .streamChatEnhanced(body.sessionId(), body.message(), userId, body.fields(), body.extraQueries(), phaseCallback);
            }

            final List<ChatSource> sources = result.getMessage().getSources();
            if (sources != null && !sources.isEmpty()) {
                synchronized (writeLock) {
                    sendSseEvent(writer, "sources", Map.of("sources", ComponentUtil.getChatApiHelper().toSourceMaps(sources)));
                }
            }

            final Map<String, Object> doneData = new LinkedHashMap<>();
            doneData.put("session_id", result.getSessionId());
            final String htmlContent = result.getMessage().getHtmlContent();
            if (htmlContent != null) {
                doneData.put("html_content", htmlContent);
            }
            synchronized (writeLock) {
                sendSseEvent(writer, "done", doneData);
            }
        } catch (final LlmException e) {
            // The callback already emitted onError to the SSE stream; do not double-send.
            logger.warn("[RAG] /api/v2/chat/stream LLM error. sessionId={}, errorCode={}", body.sessionId(), e.getErrorCode());
        } catch (final ClientDisconnectedException e) {
            // Client closed the TCP connection mid-stream; no point writing an error event
            // to a dead socket. Log at DEBUG to avoid noise in normal operation.
            logger.debug("[RAG] /api/v2/chat/stream aborted: client disconnected mid-stream. sessionId={}", body.sessionId());
        } catch (final Exception e) {
            logger.warn("[RAG] /api/v2/chat/stream failed. error={}", e.getMessage(), e);
            // Avoid double-emitting an error event when the callback already wrote one,
            // and avoid writing to a closed response body. Reuse the same writer we
            // acquired at the top — do NOT call res.getWriter() again here because the
            // container may have already closed it.
            if (!errorEmittedHolder[0] && !res.isCommitted()) {
                try {
                    synchronized (writeLock) {
                        sendSseEvent(writer, "error", Map.of("message", "internal error", "error_code", LlmException.ERROR_UNKNOWN));
                    }
                } catch (final Exception ioe) {
                    logger.warn("Failed to send SSE error after exception", ioe);
                }
            }
        } finally {
            stopKeepalivePinger(pingerFuture);
        }
    }

class_constructor:
public ChatStreamHandler() {
        // no-op — pool is created in init()
    }
